QCU_T("es", "santePublique", {
  "0": ["Elija la respuesta CORRECTA: una mutación constitucional deletérea en un gen de predisposición al cáncer de mama y de ovario BRCA 1 y BRCA 2 es",["Un factor de riesgo","Un indicador de riesgo","Un marcador de riesgo","Un síntoma del cáncer de mama"],["Falso: un factor de riesgo puede controlarse, modificarse o eliminarse, lo que es imposible en una mutación genética constitucional.","Falso: el indicador de riesgo es un marcador preclínico sin influencia causal, no una característica genética endógena.","Correcto: una mutación germinal BRCA es endógena, no modificable, y señala a un individuo vulnerable = definición de marcador de riesgo.","Falso: una mutación de predisposición no es un síntoma (manifestación clínica) del cáncer."]],
  "1": ["¿Cuál de las afirmaciones siguientes es FALSA en relación con la prevención?",["La vacunación es una medida de prevención primaria","La prevención terciaria tiene como finalidad rehabilitar al enfermo","La prevención primaria busca reducir la prevalencia de la enfermedad","La prevención secundaria es la dirigida a los enfermos en la etapa preclínica"],["Verdadero: la vacunación se cita como medida de prevención primaria (población sana, antes de la enfermedad).","Verdadero: la prevención terciaria busca la rehabilitación y la reinserción del enfermo sintomático.","FALSA: la prevención primaria reduce la INCIDENCIA; es la prevención secundaria la que actúa sobre la prevalencia.","Verdadero: la prevención secundaria se dirige a los enfermos asintomáticos en fase preclínica (cribado)."]],
  "2": ["Elija la respuesta CORRECTA. ¿Cuál es la principal vía de transmisión del VIH en Francia?",["Relaciones sexuales heterosexuales","Usuarios de drogas inyectables","Las relaciones sexuales entre hombres","Vía vertical"],["Falso para Francia: lo heterosexual predomina en el mundo, no en Occidente.","Falso: el intercambio de material de inyección no es la vía principal en Francia.","Correcto: en Occidente (Francia), la transmisión predominante es HSH (relaciones sexuales entre hombres).","Falso: la transmisión vertical está reducida a ≈0 % en Occidente."]],
  "3": ["Elija la respuesta FALSA. Se habla de transmisión directa cuando la transmisión es:",["Por las manos","Por agua contaminada","Vertical (sanguínea maternofetal)","Cutánea"],["Contacto o piel: corresponde a la transmisión directa (contacto piel-mucosas).","FALSA: el agua contaminada es un vehículo inanimado = transmisión INDIRECTA, no directa.","Verdadero: la vía vertical maternofetal se clasifica como transmisión directa.","Verdadero: la vía cutánea (contacto directo piel-piel o mucosas) es una transmisión directa."]],
  "4": ["Elija la respuesta FALSA. El fenómeno de reordenamiento vírico:",["Se ha descrito para el virus de la gripe","Da lugar a un virus reordenado","Produce el deslizamiento antigénico","Se asocia a la gripe pandémica"],["Verdadero: el reordenamiento se describe para el virus gripal de tipo A.","Verdadero: el reordenamiento produce un virus recombinante o reordenado.","FALSA: el reordenamiento produce la ruptura antigénica (variación mayor), no el deslizamiento (mutaciones puntuales menores).","Verdadero: la ruptura antigénica por reordenamiento es responsable de las pandemias gripales."]],
  "5": ["Elija la respuesta CORRECTA. El aislamiento es:",["La separación de los enfermos de los demás miembros de la sociedad durante el periodo de latencia","La separación provisional durante el periodo de incubación de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","La separación provisional durante el periodo de latencia de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","La separación de los enfermos de los demás miembros de la sociedad durante el periodo de transmisibilidad"],["Falso: el periodo es erróneo (latencia) y el aislamiento concierne a la transmisibilidad, no a la latencia.","Falso: la separación de los sujetos sanos contactos durante la incubación = definición de la cuarentena.","Falso: describe individuos sanos y un periodo de latencia, lo que no corresponde al aislamiento.","Correcto: el aislamiento = separación de los ENFERMOS durante el periodo de transmisibilidad."]],
  "6": ["Una enfermedad endémica en España cuyo agente infeccioso se transmite por el mosquito flebótomo infectado es:",["El paludismo","El dengue","La leishmaniosis","El zika"],["Falso: el paludismo lo transmite el anofeles y no es endémico ni autóctono en España (enfermedad importada).","Falso: el dengue lo transmite Aedes (mosquito tigre), no un flebótomo.","Correcto: la leishmaniosis, transmitida por el flebótomo, es la enfermedad vectorial más extendida en España.","Falso: el Zika lo transmite Aedes, no un flebótomo."]],
  "7": ["Elija la respuesta CORRECTA. Después de realizar una punción con aguja seca o «dry needling», el gesto correcto es:",["Volver a encapuchar la aguja antes de tirarla al contenedor de agujas más próximo","Eliminar directamente la aguja en el contenedor de agujas más próximo","Sumergir la aguja rápidamente en un baño detergente antes de eliminarla en el contenedor de agujas más próximo","Tirar la aguja a la basura, porque no ha estado en contacto con la sangre del paciente"],["Falso: nunca hay que volver a encapuchar la aguja (riesgo de pinchazo accidental).","Correcto: eliminar directamente la aguja en el contenedor más próximo, sin volver a encapucharla.","Falso: la inmersión en un detergente es inútil y peligrosa; la aguja va al contenedor.","Falso: una aguja usada nunca se tira a la basura, sino a un contenedor específico."]],
  "8": ["Una hepatitis vírica que se vuelve crónica en >50 % de los casos y que no tiene vacuna para prevenirla es una:",["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis B o C"],["Hepatitis A: nunca se vuelve crónica y existe una vacuna — falso","Hepatitis B: ~5 % de cronicidad y vacuna universal disponible — falso","Hepatitis C: ~70 % de cronicidad y SIN vacuna — corresponde exactamente","B o C: la hepatitis B no cumple ninguno de los dos criterios — falso"]],
  "9": ["Elija la respuesta FALSA en relación con la multirresistencia:",["Se habla de multirresistencia cuando una bacteria ya no es sensible a 3 antibióticos de la misma familia","Se asocia clásicamente a las infecciones nosocomiales, aunque también se halla en las infecciones comunitarias","Prolonga el número de días de estancia en el hospital","Los pacientes tratados recientemente con antibióticos tienen más riesgo"],["FALSA (respuesta que se pide): la multirresistencia = no sensible a 3 familias DIFERENTES, no de la misma familia","Verdadero: clásicamente nosocomial, pero también comunitaria (atraviesa la barrera del hospital)","Verdadero: prolonga la duración de la estancia hospitalaria","Verdadero: los antibióticos previos son un factor de riesgo reconocido"]],
  "10": ["Elija la respuesta CORRECTA. Una infección se llama nosocomial si la contrae:",["Un paciente que va al hospital 3 veces por semana para dializarse","Un paciente que ha sido ingresado en el hospital al menos 24 h antes de empezar a tener los síntomas","Un paciente con una infección que aparece en una cicatriz quirúrgica en los 15 días posteriores a la cirugía","Todas las respuestas son correctas"],["Diálisis ambulatoria = infección asociada a la asistencia sanitaria, pero no nosocomial en sentido estricto (adquirida en el hospital) — falso","El plazo establecido es ≥48 h, no 24 h — falso","Infección de cicatriz quirúrgica en los 15 días (< 30 días) = nosocomial — CORRECTO","No todas son correctas, puesto que las dos primeras son erróneas — falso"]],
  "11": ["¿Cuál es el virus cuya vía de transmisión más frecuente es el contacto con sangre contaminada (vía sanguínea)?",["Hepatitis A","VIH","Hepatitis C","Hepatitis C y VIH"],["VHA: transmisión sanguínea baja (+), con vía orofecal predominante — falso","VIH: transmisión sexual predominante, y sanguínea solo ++ — falso","VHC: transmisión parenteral o sanguínea principal (+++++) — CORRECTO","C y VIH: el VIH es sobre todo sexual, de modo que añadirlo es falso"]],
  "12": ["¿Qué es la infectividad?",["La capacidad de los microorganismos, en un huésped de una especie dada, de establecerse en un medio y multiplicarse en él","La capacidad de un microorganismo de pasar de un huésped a otro","La aptitud de un microorganismo para provocar la enfermedad en el huésped infectado","La capacidad de un microorganismo de provocar infecciones graves"],["Establecerse en un tejido o medio y multiplicarse en él = definición de la infectividad — CORRECTO","Pasar de un huésped a otro = transmisibilidad o contagiosidad — falso","Provocar la enfermedad = poder patógeno o patogenicidad — falso","Provocar infecciones graves = virulencia — falso"]],
  "13": ["Elija la respuesta falsa. Se habla de transmisión directa cuando la transmisión es:",["Por las manos","Por agua contaminada","Vertical","Cutánea"],["Por las manos: transmisión por contacto (puede corresponder al contacto directo) — no es la respuesta","FALSA (respuesta que se pide): el agua contaminada = vehículo inanimado = transmisión INDIRECTA","Vertical: figura como transmisión directa — no es la respuesta","Cutánea: contacto piel a piel = transmisión directa — no es la respuesta"]],
  "14": ["Elija la respuesta falsa. El fenómeno de reordenamiento vírico:",["Se ha descrito para el virus de la gripe","Da lugar a un virus reordenado","Produce el deslizamiento antigénico","Se asocia a la gripe pandémica"],["Verdadero: el reordenamiento (reasociación) se describe para la gripe (tipo A)","Verdadero: da lugar a un virus reordenado","FALSA (respuesta que se pide): el reordenamiento produce la RUPTURA antigénica, no el deslizamiento (mutaciones puntuales)","Verdadero: se asocia a la gripe pandémica"]],
  "15": ["Elija la respuesta CORRECTA. La presencia habitual de una enfermedad infecciosa en una población determinada o en una región precisa, con una incidencia estable, se llama:",["Casos esporádicos","Endemia","Epidemia","Pandemia"],["Casos esporádicos = casos aislados, no una presencia habitual","Endemia = presencia habitual con incidencia estable","Epidemia = crecimiento rápido de la incidencia","Pandemia = epidemia a escala mundial"]],
  "16": ["Elija la respuesta CORRECTA. El periodo de latencia es:",["El tiempo durante el cual hay signos o síntomas de infección","El tiempo durante el cual la infección puede transmitirse","El tiempo transcurrido desde la infección hasta que se vuelve contagiosa","El tiempo transcurrido entre la exposición a un organismo patógeno y la aparición de signos y síntomas"],["Falso = define el periodo clínico","Falso = define el periodo de transmisibilidad","Verdadero = latencia: desde la exposición hasta la contagiosidad","Falso = define el periodo de incubación"]],
  "17": ["Elija la respuesta CORRECTA. La reducción del número de casos de una enfermedad infecciosa hasta una incidencia nula en un espacio geográficamente limitado se llama:",["Intervención sanitaria","Control","Erradicación","Eliminación"],["Término genérico, no definido como tal","Control = reducción de la incidencia, no hasta cero","Erradicación = cero casos a escala PLANETARIA","Eliminación = interrupción en una zona limitada"]],
  "18": ["Elija la respuesta CORRECTA. La cuarentena:",["Es la separación de los enfermos de los demás miembros de la sociedad durante el periodo de transmisibilidad","Es la separación de los enfermos de los demás miembros de la sociedad durante el periodo de latencia","Es la separación provisional durante el periodo de latencia de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","Es la separación provisional durante el periodo de incubación de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa"],["Describe el aislamiento (enfermos, transmisibilidad)","Falso: concierne a los enfermos, no es la cuarentena","Falso: la duración es el periodo de incubación, no la latencia","Verdadero = cuarentena: individuos sanos contactos, con una duración igual al periodo de incubación"]],
  "19": ["Elija la respuesta CORRECTA. El fenómeno de ruptura antigénica del virus de la gripe:",["Es la causa de la adaptación anual de las vacunas","Origina un virus reordenado","Comporta variaciones menores de las proteínas H y N","Se asocia a la gripe estacional"],["Falso = es el deslizamiento (adaptación anual)","Verdadero = ruptura: reordenamientos genéticos, virus reordenado","Falso = variaciones menores = deslizamiento","Falso = el deslizamiento se asocia a la gripe estacional"]],
  "20": ["Elija la respuesta CORRECTA. El proceso que elimina casi todos los microorganismos patógenos reconocidos, pero no necesariamente todas las formas microbianas (no las esporas bacterianas) sobre objetos se llama:",["Limpieza","Antisepsia","Esterilización","Desinfección"],["Limpieza = simple eliminación de la suciedad","Antisepsia = sobre piel o mucosas, no sobre objetos","Esterilización = elimina TODO, incluidas las esporas","Desinfección = formas vegetativas (no las esporas) sobre objeto inanimado"]],
  "21": ["¿Cuál de las siguientes enfermedades de transmisión vectorial puede prevenirse con una vacuna?",["Paludismo","Zika","Fiebre amarilla","Enfermedad de Chagas"],["Paludismo: prevención con quimioprofilaxis, no con la vacuna estándar que se cita","Zika: sin vacuna","Fiebre amarilla: vacuna existente (enfermedad vectorial vacunable)","Enfermedad de Chagas: sin vacuna"]],
  "22": ["Elija la respuesta CORRECTA. El periodo de tiempo (mediana) tras la infección en el que el paciente VIH seropositivo permanece asintomático es:",["2 meses","2 años","8 meses","8 años"],["2 meses: demasiado corto","2 años: incorrecto","8 meses: incorrecto","8 años = mediana de la fase crónica asintomática"]],
  "23": ["Elija la respuesta CORRECTA. Una infección en una persona mayor que vive en una residencia de ancianos es una infección:",["Asociada a la asistencia sanitaria","Nosocomial","Comunitaria","Multirresistencia"],["CORRECTO: una infección en un residente de una residencia de ancianos (cuidados de larga duración) es una infección asociada a la asistencia sanitaria, categoría más amplia que la nosocomial.","Nosocomial = adquirida en el HOSPITAL (plazo ≥48 h tras el ingreso), no en una residencia de ancianos.","Comunitaria = adquirida fuera de todo contexto asistencial; no corresponde a un lugar de cuidados de larga duración.","La multirresistencia califica a una bacteria, no el contexto de adquisición de la infección."]],
  "24": ["Elija la respuesta CORRECTA. La fuente de infección de la legionelosis puede ser:",["Un paciente infectado por Legionella pneumophila","Una torre de refrigeración, un jacuzzi, un spa, una piscina, las duchas, etc.","Las gotículas transmitidas por vía aérea","Todas las respuestas son correctas"],["Falso: la legionelosis NO se contagia de persona a persona, de modo que un paciente no es fuente.","CORRECTO: la fuente es la aerosolización de agua (torres de refrigeración, jacuzzi, spa, duchas, fuentes).","Describe la vía de transmisión (aérea indirecta), no la fuente de infección.","Falso, puesto que la primera y la tercera proposiciones son incorrectas."]],
  "25": ["¿Cuál de las siguientes afirmaciones es CORRECTA para la virulencia?",["Capacidad del microorganismo de provocar la enfermedad en los infectados","Capacidad de un microorganismo, en un huésped de una especie dada, de establecerse en un tejido y multiplicarse en él","Puede medirse mediante la tasa de letalidad","Puede medirse mediante la tasa de patogenicidad"],["Define la patogenicidad o poder patógeno, no la virulencia.","Define la infectividad, no la virulencia.","CORRECTO: la virulencia (capacidad de provocar una infección grave) se mide mediante la tasa de letalidad.","La tasa de patogenicidad no es la medida de la virulencia."]],
  "26": ["Elija la respuesta correcta. La fiebre amarilla está habitualmente presente en Brasil con una incidencia estable a lo largo del tiempo; se habla de:",["Endemia","Epidemia","Casos esporádicos","Pandemia"],["CORRECTO: presencia habitual con incidencia estable en una región = endemia.","Epidemia = crecimiento rápido de la incidencia, no una incidencia estable.","Casos esporádicos = casos aislados, no una presencia habitual estable.","Pandemia = epidemia a escala mundial, no aplicable aquí."]],
  "27": ["¿Cuál de los siguientes enunciados NO es un objetivo de la epidemiología?",["Establecer la frecuencia y la distribución de los enfermos","El estudio cuantitativo y cualitativo de las poblaciones humanas y de sus dinámicas","Evaluación del funcionamiento de los servicios asistenciales","Describir la historia natural de las enfermedades y los factores que determinan su evolución"],["Objetivo de la epidemiología descriptiva (frecuencia y distribución).","NO es un objetivo de la epidemiología: es la definición de la DEMOGRAFÍA.","Objetivo de la epidemiología evaluativa o de intervención.","Objetivo epidemiológico: historia natural y determinantes de las enfermedades."]],
  "28": ["Una inequidad en salud es:",["toda desigualdad hallada dentro de un mismo país o entre países diferentes","una desigualdad derivada de la elección individual de las personas","una desigualdad evitable","una desigualdad que no puede modificarse ni controlarse"],["Describe una desigualdad en general, no específicamente una inequidad.","Una inequidad no se define por la elección individual.","CORRECTO: una inequidad es una desigualdad de salud EVITABLE (injusta).","Lo que no puede modificarse corresponde a un marcador de riesgo, no a una inequidad."]],
  "29": ["La esperanza de vida es:",["un indicador de salud","un indicador sintético de salud","un determinante de salud ligado a las condiciones de vida y de trabajo","a y c son correctas"],["CORRECTO: la esperanza de vida es el indicador de salud más utilizado para comparar la mortalidad.","Los indicadores sintéticos combinan mortalidad y calidad de vida (AVAD, AVAC); la esperanza de vida no es uno de ellos.","La esperanza de vida es un indicador, no un determinante de salud.","Falso, porque la proposición c es incorrecta."]],
  "30": ["Elija la respuesta incorrecta en relación con la tuberculosis",["primer factor de mortalidad en los VIH seropositivos","la incidencia baja alrededor de un 2 % al año en el mundo","un 90 % de los infectados no desarrolla la enfermedad","los individuos con tuberculosis latente no presentan signos ni síntomas, pero pueden transmitir la infección"],["Verdadero: la TB es una causa mayor de mortalidad en los VIH+ (sinergia TB/VIH).","Verdadero: la incidencia de la TB disminuye alrededor de un 2 % al año en el mundo.","Verdadero: ≈90 % de los infectados conservan bacilos latentes y no desarrollan la enfermedad.","Respuesta INCORRECTA (falsa): la TB latente NO es bacilífera ni contagiosa, y no transmite la infección."]],
  "31": ["Elija la respuesta falsa. El fenómeno de deslizamiento antigénico del virus de la gripe",["es la causa de la adaptación anual de las vacunas","se asocia a la gripe estacional","origina un virus reordenado","comporta mutaciones en las proteínas H y N"],["Verdadero: el deslizamiento (drift) impone la adaptación anual de la vacuna.","Verdadero: el drift es responsable de las variaciones estacionales.","FALSO (respuesta que se busca): el virus reordenado procede de la ruptura antigénica (shift), no del deslizamiento.","Verdadero: el drift = mutaciones puntuales en H y N."]],
  "32": ["Elija la respuesta incorrecta: el fenómeno de reordenamiento vírico",["se ha descrito para el virus de la gripe","da lugar a un virus reordenado","produce el deslizamiento antigénico","se asocia a la gripe pandémica"],["Verdadero: el reordenamiento (ruptura) se describe en el virus gripal.","Verdadero: el reordenamiento genera un virus reordenado.","FALSO (respuesta que se busca): el reordenamiento produce la ruptura antigénica, no el deslizamiento (que proviene de mutaciones puntuales).","Verdadero: la ruptura o reordenamiento origina las pandemias."]],
  "33": ["El aislamiento es:",["la separación de los enfermos y de los demás miembros de la sociedad durante el periodo de latencia","la separación provisional durante el periodo de incubación de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","la separación provisional durante el periodo de latencia de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","la separación de los enfermos de los demás miembros de la sociedad durante el periodo de transmisibilidad"],["Falso: periodo erróneo (latencia en lugar de transmisibilidad).","Falso: describe la cuarentena (sujetos sanos, periodo de incubación).","Falso: sujetos sanos = cuarentena, y periodo erróneo.","Correcto: aislamiento = separación de los enfermos durante el periodo de transmisibilidad."]],
  "34": ["Elija la respuesta correcta: la hepatitis que tiene la vía sanguínea (contacto con sangre contaminada) como vía de transmisión en el origen de la mayoría de los casos infectados es",["hepatitis A","hepatitis B","hepatitis C","hepatitis B y C"],["Falso: hepatitis A = vía orofecal.","Falso: hepatitis B = sobre todo sexual en los países desarrollados.","Correcto: hepatitis C = transmisión parenteral (sangre) en el origen de la mayoría de los casos.","Falso: solo la C tiene la sangre como vía principal."]],
  "35": ["¿Cuál es la principal vía de transmisión del VIH en Francia?",["vía vertical","las relaciones sexuales entre hombres","usuarios de drogas inyectables","relaciones sexuales heterosexuales"],["Falso: la vía vertical es casi nula en Occidente.","Correcto: en Occidente (Francia) la vía predominante es HSH (relaciones entre hombres).","Falso: el uso de drogas por vía intravenosa no es la vía principal.","Falso: lo heterosexual predomina en el mundo, no en Francia."]],
  "36": ["¿Cuál de las afirmaciones siguientes define una característica de una pandemia?",["Epidemia que afecta a varios países y continentes","nueva enfermedad o enfermedad que no estaba presente desde hacía tiempo","considerada una urgencia de salud pública de alcance internacional","todas las respuestas son correctas"],["Correcto: pandemia = epidemia que afecta a varios países o continentes (escala mundial).","Falso: una pandemia no es por definición una enfermedad nueva.","Falso: no se declara obligatoriamente una emergencia de salud pública de importancia internacional.","Falso: la segunda y la tercera proposiciones no son características definitorias."]],
  "37": ["Tasa de letalidad",["representa la probabilidad de adquirir una infección","mide la virulencia de un agente infeccioso","mide la patogenicidad de un agente infeccioso","es la relación entre el número de individuos infectados que mueren y el número total de personas expuestas"],["Falso: la probabilidad de adquirir una infección corresponde a la infectividad o a la tasa de ataque.","Correcto: la virulencia se mide mediante la tasa de letalidad (p. ej. Ébola 40-60 %, COVID ~1,1 %).","Falso: la patogenicidad es la aptitud para provocar la enfermedad, no la letalidad.","Falso: denominador erróneo (número de enfermos o infectados, no el total de expuestos)."]],
  "38": ["Se acaba de comercializar un nuevo medicamento antivírico de tipo PrEP para los homosexuales. ¿Qué ocurrirá?",["la tasa de incidencia disminuye","la tasa de incidencia aumenta","la prevalencia del sida aumentará","la prevalencia del sida aumenta"],["Correcto: la PrEP previene la infección, de modo que la incidencia (nuevos casos) disminuye.","Falso: la incidencia no puede aumentar con una profilaxis eficaz.","Falso: menos infecciones → no hay aumento de la prevalencia del sida.","Falso: duplicado, con el mismo razonamiento erróneo."]],
  "39": ["Elija la respuesta falsa en relación con la multirresistencia",["se habla de multirresistencia cuando una bacteria ya no es sensible a 3 antibióticos de la misma familia","se asocia clásicamente a las infecciones nosocomiales, aunque también se halla en las infecciones comunitarias","prolonga el número de estancias en el hospital","los pacientes tratados recientemente con antibióticos tienen más riesgo"],["FALSA (respuesta que se busca): una bacteria multirresistente ya no es sensible a los antibióticos de TRES familias DIFERENTES, no de la misma familia","Verdadero: ligada a las infecciones nosocomiales, pero atraviesa la barrera hacia la comunidad","Verdadero: la multirresistencia prolonga las estancias hospitalarias","Verdadero: la antibioterapia previa = factor de riesgo reconocido"]],
  "40": ["La inactivación de un alto porcentaje de formas vegetativas de bacterias que se encuentran en la piel o las mucosas con el fin de anular su potencial infeccioso se llama",["limpieza","desinfección","antisepsia","esterilización"],["La limpieza retira la suciedad y no se dirige a las formas vegetativas de la piel","La desinfección concierne a los objetos inanimados, no a la piel ni a las mucosas","Correcto: antisepsia = inactivación de las formas vegetativas en piel, mucosas y heridas","La esterilización elimina toda vida, incluidas las esporas, en material, no en la piel"]],
  "41": ["La respuesta verdadera sobre la cuarentena:",["es la separación provisional durante el periodo de incubación de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","es la separación provisional durante el periodo de latencia de los individuos sanos que han estado en contacto con un enfermo con una enfermedad contagiosa","es la separación provisional durante el periodo de latencia de los individuos contagiosos que han estado en contacto con un enfermo con una enfermedad contagiosa","es la separación provisional durante el periodo de latencia de los individuos portadores de una enfermedad que todavía no es contagiosa"],["Correcto: cuarentena = separación de individuos SANOS que han estado en contacto, con una duración igual al periodo de incubación","Falso: es el periodo de incubación, no la latencia","Falso: concierne a los individuos sanos, no a los contagiosos, y a la incubación","Falso: periodo erróneo (latencia) y concierne a sanos que han estado en contacto"]],
  "42": ["¿Qué es el COMENSALISMO?",["el patógeno se beneficia, mientras que el huésped no obtiene nada de la interacción.","el patógeno y el huésped obtienen ambos un beneficio de esa interacción","El comensalismo coincide con el concepto de simbiosis y de mutualismo","Todo es falso"],["Correcto: comensalismo = el microorganismo se beneficia (vive y se multiplica) mientras que el huésped no obtiene ni beneficio ni daño","Falso: beneficio mutuo = mutualismo, no comensalismo","Falso: el comensalismo se distingue del mutualismo","Falso, puesto que la primera proposición es exacta"]],
  "43": ["Una encuesta transversal puede utilizarse para conocer:",["la incidencia de una enfermedad","los factores de riesgo de una enfermedad","la prevalencia de una enfermedad","La causalidad de una enfermedad"],["La incidencia exige un seguimiento (estudio longitudinal), no un corte transversal","Los factores de riesgo corresponden a estudios analíticos (cohorte, casos y controles)","Correcto: la prevalencia se obtiene con un estudio transversal, sin seguimiento","La causalidad exige una anterioridad temporal, no medible en un transversal"]],
  "44": ["¿Cuál de las siguientes afirmaciones es CORRECTA para la virulencia?",["Capacidad del microorganismo de provocar la enfermedad en los infectados","Capacidad de un microorganismo, en un huésped de una especie dada, de establecerse en un tejido y multiplicarse en él","Puede medirse mediante la tasa de letalidad","Puede medirse mediante la tasa de patogenicidad"],["Provocar la enfermedad = poder patógeno o patogenicidad, no virulencia","Establecerse y multiplicarse en un tejido = infectividad","Correcto: la virulencia (gravedad de la infección) se mide mediante la tasa de letalidad","No existe una medida mediante una tasa de patogenicidad para la virulencia"]],
  "45": ["Elija la respuesta CORRECTA. La fiebre amarilla es habitual en Brasil con una incidencia estable a lo largo del tiempo; se habla de:",["Endemia","Epidemia","Casos esporádicos","Pandemia"],["Correcto: presencia habitual con incidencia estable en el tiempo = endemia","Epidemia = crecimiento rápido de la incidencia, no estable","Casos esporádicos = casos aislados, no una presencia habitual","Pandemia = epidemia a escala mundial en varios continentes"]],
  "46": ["Elija la respuesta CORRECTA. El reservorio de Legionella pneumophila es:",["El agua caliente","El paciente infectado","Las torres de refrigeración","Los alimentos contaminados"],["Correcto: el reservorio de Legionella es el agua (aguas superficiales y después conducciones y agua caliente donde proliferan).","No hay reservorio humano: no existe contagio de persona a persona.","Las torres de refrigeración son la FUENTE de infección (aerosolización), no el reservorio.","La legionelosis es una enfermedad ambiental hídrica, no alimentaria."]],
  "47": ["Elija la respuesta CORRECTA. La fuente de infección de la tuberculosis puede ser:",["Todas las personas con infección latente o activa","Todos los enfermos bacilíferos","Los aerosoles de las gotículas expectoradas","Todas las personas con la prueba de Mantoux positiva"],["Falso: la infección latente (no bacilífera) no es contagiosa y, por tanto, no es fuente.","Correcto: la fuente de infección es el enfermo bacilífero según el resumen.","Los aerosoles de las gotículas son la vía o puerta de salida, no la fuente.","Un Mantoux positivo solo señala la infección, no la contagiosidad."]],
  "48": ["Elija la respuesta CORRECTA. ¿Cuál de las siguientes es una enfermedad de transmisión sexual?",["Triquinosis","Toxoplasmosis","Tricomoniasis","Hidatidosis"],["Triquinosis: infección alimentaria parasitaria, no una ITS.","Toxoplasmosis: transmisión alimentaria o congénita, no sexual.","Correcto: la tricomoniasis (Trichomonas vaginalis) es una ITS por protozoo.","Hidatidosis: parasitosis (equinococo), no sexual."]],
  "49": ["Elija la respuesta CORRECTA. ¿Cuál de las siguientes es la infección alimentaria más frecuente en la Unión Europea?",["Listeriosis","Infección por Escherichia coli","Campilobacteriosis","Salmonelosis"],["Listeria es la zoonosis alimentaria más GRAVE, no la más frecuente.","E. coli no es la infección alimentaria más frecuente.","Correcto: Campylobacter es la zoonosis e infección alimentaria más frecuente en la UE.","La salmonelosis es la más frecuente de los BROTES epidémicos, no la infección más frecuente."]],
  "50": ["Elija la respuesta CORRECTA en relación con el anisakis:",["La medida de prevención es congelar el alimento crudo durante al menos 24 h a ≤ −20 °C","Los alimentos implicados con mayor frecuencia son la carne y los pescados","Es una bacteria que produce toxinas que provocan la enfermedad","Todas las respuestas son correctas"],["Correcto: prevención mediante congelación a ≤ −20 °C durante ≥ 24 h (pescado crudo).","Falso: la anisakiasis proviene del pescado crudo o mal cocinado, no de la carne.","Falso: el anisakis es un parásito (nematodo), no una bacteria con toxinas.","Falso: puesto que dos proposiciones son incorrectas."]],
  "51": ["Elija la respuesta FALSA en relación con las infecciones de transmisión vectorial:",["Son más frecuentes en las regiones tropicales y subtropicales","Las pulgas y las garrapatas son posibles vectores de algunas enfermedades","Hay una especificidad: un patógeno transmitido por mosquitos puede transmitirse por distintos géneros de mosquitos, pero no por otros tipos de vectores","Los patógenos transmitidos por los vectores pueden ser bacterias, virus o parásitos"],["Verdadero: las enfermedades vectoriales predominan en zonas tropicales y subtropicales.","Verdadero: las pulgas y las garrapatas son vectores posibles.","FALSA (respuesta que se pide): la especificidad patógeno-vector es estricta (p. ej. Plasmodium = solo Anopheles), y un patógeno no se transmite indistintamente por varios géneros de mosquitos.","Verdadero: los agentes vectoriales pueden ser bacterias, virus o parásitos."]],
  "52": ["Elija la respuesta CORRECTA. ¿Cuál de los siguientes patógenos de transmisión vectorial puede transmitirse también por vía sexual?",["Plasmodium","Virus Zika","Virus de la fiebre amarilla","Virus Chikungunya"],["Plasmodium (paludismo): transmisión únicamente vectorial (mosquito).","Correcto: el virus Zika, vectorial, se transmite también por vía sexual.","Fiebre amarilla: transmisión vectorial únicamente.","Chikungunya: transmisión vectorial, no sexual."]],
  "53": ["Elija la respuesta FALSA en relación con las infecciones por vía sexual:",["La vía vertical es con frecuencia una posible vía de transmisión","Afectan únicamente a los hombres que tienen sexo con hombres","Tienen consecuencias sobre la salud reproductiva de las mujeres","La mayoría de las infecciones son asintomáticas"],["VERDADERO: la vía vertical (embarazo, parto, lactancia) sí es una vía de transmisión de las ITS.","FALSA (respuesta que se busca): las ITS afectan a todo el mundo, no solo a los HSH; la heterosexualidad domina en el mundo.","VERDADERO: tienen consecuencias reproductivas en la mujer (salpingitis, esterilidad, embarazo ectópico, prematuridad).","VERDADERO: el resumen subraya que la mayoría de los casos son asintomáticos, lo que favorece la transmisión."]],
  "54": ["Elija la respuesta CORRECTA. La hepatitis que tiene la vía sanguínea (contacto con sangre contaminada) como vía de transmisión principal (mayoría de los casos infectados) es:",["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis B y C"],["No: la hepatitis A es orofecal, con transmisión sanguínea baja.","No: la hepatitis B es sobre todo sexual (países desarrollados), no mayoritariamente sanguínea.","Correcto: la hepatitis C tiene la vía parenteral o sanguínea como vía principal (tabla: sanguínea +++++).","No: solo la C tiene la sangre como vía principal, no la B."]],
  "55": ["Elija la respuesta CORRECTA. El tratamiento antirretroviral que reduce el desarrollo de comorbilidades y mejora la esperanza de vida de los infectados por el VIH",["Aumenta la incidencia de la infección por el VIH","Reduce la incidencia de la infección por el VIH","Aumenta la prevalencia de la infección por el VIH","Reduce la prevalencia de la infección por el VIH"],["No: el tratamiento no hace aparecer nuevos casos y no aumenta la incidencia.","No: reducir la incidencia corresponde a la prevención y a la transmisión, no a la mejoría de la supervivencia que se describe.","Correcto: al alargar la supervivencia (duración), P = I × D aumenta y por tanto la prevalencia aumenta.","No: la prevalencia aumenta al contrario, porque los pacientes viven más tiempo."]],
  "56": ["Elija la respuesta CORRECTA. La mayoría de los estudios epidemiológicos muestran que la vacuna BCG es un factor de protección frente a la tuberculosis porque el riesgo relativo es:",["Superior a 1","Igual a 1","Inferior a 1","Un marcador de riesgo"],["No: un RR > 1 = factor de riesgo, lo contrario de un factor protector.","No: un RR = 1 significa ausencia de asociación.","Correcto: un factor de protección tiene un RR < 1 (menor incidencia en los vacunados).","No: un marcador de riesgo no es modificable y no es un valor de RR."]],
  "57": ["Elija la respuesta CORRECTA. ¿De qué forma parte la respuesta a la vacunación?",["La inmunidad innata","La inmunidad adquirida pasiva","La inmunidad adquirida activa natural","La inmunidad adquirida activa artificial"],["No: la inmunidad innata no implica memoria ni vacunación.","No: pasiva = aporte de anticuerpos externos (inmunoglobulinas), no la vacunación.","No: activa natural = inmunidad adquirida tras una infección real.","Correcto: la vacuna introduce un antígeno de forma artificial = inmunidad adquirida activa artificial."]],
  "58": ["Elija la respuesta CORRECTA. Las vacunas vivas atenuadas:",["Son menos reactógenas que las inactivadas","La respuesta inmunitaria es menos duradera","En algunas de ellas hay que añadir adyuvantes como el aluminio","Están contraindicadas en inmunodeprimidos y embarazadas"],["Falso: las vacunas vivas atenuadas son generalmente más reactógenas.","Falso: su respuesta inmunitaria es más duradera (a menudo de por vida).","Falso: son las inactivadas las que necesitan adyuvantes (aluminio), no las vivas.","Correcto: están contraindicadas en inmunodeprimidos y embarazadas (contraindicaciones de las vacunas vivas)."]],
  "59": ["Elija la respuesta CORRECTA. Se habla de multirresistencia cuando:",["Una bacteria ya no es sensible a los antibióticos de tres familias diferentes (mientras que antes lo era)","Una bacteria ya no es sensible a tres antibióticos (mientras que antes lo era)","Una bacteria ya no es sensible a todos los antibióticos","Una bacteria aislada en el medio hospitalario"],["Correcto: la multirresistencia = pérdida de sensibilidad a los antibióticos de tres FAMILIAS diferentes.","No: se trata de tres familias, no simplemente de tres antibióticos.","No: no necesariamente a todos los antibióticos.","No: estar aislada en el hospital no define la multirresistencia."]],
  "60": ["¿Cuál de las siguientes afirmaciones es FALSA sobre la salud?",["La salud es un concepto dinámico y cambiante según el contexto histórico, cultural y social","La salud de la población es responsabilidad de los Estados, que deben protegerla","La salud es un derecho de la persona como miembro de una comunidad, pero también una responsabilidad que hay que promover","La salud de la población depende exclusivamente de los servicios sanitarios"],["Verdadero: la salud es un concepto dinámico y cambiante según el contexto.","Verdadero: la protección de la salud es una responsabilidad de los Estados (Constituciones francesa y española).","Verdadero: derecho Y responsabilidad que hay que promover (carta, promoción de la salud).","FALSA: la salud depende de múltiples determinantes (Lalonde: biología, medio ambiente, estilo de vida, sistema sanitario), no EXCLUSIVAMENTE de los servicios sanitarios."]],
  "61": ["En un país donde la esperanza de vida es de 83 años, una mujer que se queda ciega (coeficiente de ponderación de la discapacidad = 0,3) a los 50 años a causa de un accidente de coche fallece a los 60 años. ¿Cuál es el valor del AVAD?",["26","36","23","33"],["26 = AVP (83−60 = 23) + AVD (10 años × 0,3 = 3) → correcto (AVAD = mortalidad + morbilidad).","36: resultado erróneo.","23: solo cuenta los AVP y olvida los años vividos con discapacidad.","33: cálculo erróneo."]],
  "62": ["¿Cuál de las siguientes afirmaciones es FALSA sobre el índice coyuntural de fecundidad?",["Es la tasa de fecundidad por tramo de edad","Es el número medio de hijos por mujer","Es un índice de la demografía dinámica o longitudinal","El valor mínimo para el nivel de reemplazo es 2,1"],["Verdadero: el índice coyuntural de fecundidad se construye a partir de la suma de las tasas de fecundidad por tramo de edad.","Verdadero: número medio de hijos por mujer.","FALSA: el índice coyuntural de fecundidad es un indicador coyuntural o TRANSVERSAL (generación ficticia), no longitudinal.","Verdadero: umbral de reemplazo ≈ 2,1 hijos."]],
  "63": ["Elija la respuesta CORRECTA. A partir del análisis de una población en la que los porcentajes de sujetos en los tramos de edad 0-14 años, 15-49 años y ≥50 años son similares, se ha decidido que se trata de una población estacionaria. ¿Qué índice se utilizó?",["Índice de Fritz","Índice de Swaroop","Índice de Sundbärg","Índice de Burgdöfer"],["Fritz: relación 0-19 / 20-59 años, no corresponde.","Swaroop: índice de mortalidad (fallecidos ≥50 años / total), no la estructura de edad.","Sundbärg: compara 0-14 y ≥50 años (base 15-49) → población estacionaria si las proporciones son similares → correcto.","Burgdöfer: compara 5-14 con 45-64 años, no corresponde."]],
  "64": ["Elija la respuesta CORRECTA. Una encuesta transversal puede utilizarse para conocer:",["Los factores de riesgo de una enfermedad","La incidencia de una enfermedad","La prevalencia de una enfermedad","b) y c) son correctas"],["Factores de riesgo: la asociación es posible, pero no se propone ninguna opción «a)+c)»; no es la respuesta esperada.","Incidencia: exige un seguimiento (estudio longitudinal), imposible en un transversal.","Prevalencia: se mide con un estudio transversal, sin seguimiento → correcto.","b)+c): falso, porque la incidencia no es medible con una encuesta transversal."]],
  "65": ["Elija la respuesta CORRECTA. En la Unión Europea, ¿en qué grupo de población es más elevada la incidencia de la clamidiasis?",["Mujeres heterosexuales <25 años","Mujeres heterosexuales >25 años","Hombres heterosexuales <25 años","Hombres heterosexuales >25 años"],["Mujeres heterosexuales <25 años: incidencia de clamidiasis más elevada en la UE (mujeres jóvenes, datos del ECDC) → correcto.","Mujeres >25 años: incidencia claramente menor.","Hombres <25 años: menos afectados que las mujeres jóvenes.","Hombres >25 años: incidencia menor."]],
  "66": ["Elija la respuesta CORRECTA. Una característica endógena que está significativamente ligada a una enfermedad en la etapa preclínica sin influir en su aparición es:",["Un síntoma de la enfermedad","Un indicador de riesgo","Un marcador de riesgo","Un factor de riesgo"],["Síntoma: manifestación clínica, no una característica de la fase preclínica.","Indicador de riesgo: característica ligada a la enfermedad en fase PRECLÍNICA, SIN influencia en su aparición → correcto.","Marcador de riesgo: endógeno, pero señala una vulnerabilidad constitucional (edad, sexo, genes), no se define por la fase preclínica.","Factor de riesgo: precede E influye en la aparición (al contrario de lo que plantea el enunciado)."]],
  "67": ["¿Cuál de las afirmaciones siguientes es FALSA?",["La mayoría de las bacterias que pueblan nuestras superficies y ocupan nuestras cavidades mantienen una relación de comensalismo o de simbiosis con nuestro organismo.","Las alteraciones del microbioma pueden conducir a enfermedades, aunque la relación entre este y nuestro organismo todavía se comprende mal.","Una enfermedad infecciosa será siempre una enfermedad transmisible","A veces, un microbio perteneciente al microbioma llega a producir una enfermedad; se hablaría entonces de una infección endógena."],["Verdadero: la flora comensal o simbiótica puebla nuestras superficies y cavidades (microbioma).","Verdadero: las alteraciones del microbioma (disbiosis) pueden conducir a enfermedades.","FALSA: una enfermedad infecciosa no siempre es transmisible (infección endógena por la propia flora; Legionella o tétanos no contagiosos de persona a persona).","Verdadero: un microbio del microbioma puede provocar una infección llamada endógena."]],
  "68": ["Elija la respuesta CORRECTA. ¿Cuál de los siguientes microorganismos causa infecciones nosocomiales y presenta con frecuencia resistencia a los antibióticos?",["Trypanosoma cruzi","Pseudomonas aeruginosa","Clostridium botulinum","Treponema pallidum"],["Trypanosoma cruzi: protozoo vectorial (Chagas), no nosocomial.","CORRECTO: Pseudomonas aeruginosa = patógeno nosocomial clásico, a menudo multirresistente a los antibióticos.","Clostridium botulinum: intoxicación alimentaria (botulismo), no nosocomial resistente.","Treponema pallidum: agente de la sífilis (ITS), sensible a la penicilina."]],
  "69": ["Elija la respuesta FALSA en relación con las enfermedades cardiovasculares",["Representan el 40 % de las enfermedades no transmisibles.","Más de 3/4 de las muertes ligadas a las enfermedades cardiovasculares se producen en países de renta baja e intermedia.","La hipertensión arterial contribuye al menos al 40 % de todas las enfermedades cardiovasculares.","Los ictus representan la primera causa de muerte en Francia."],["Aproximadamente verdadero: las enfermedades cardiovasculares y el ictus representan ~40-45 % de las enfermedades no transmisibles (el resumen cita un 45 %).","Verdadero: > 3/4 de las muertes por enfermedad cardiovascular se producen en países de renta baja e intermedia.","Verdadero: la HTA contribuye al menos al 40 % de las enfermedades cardíacas y los ictus.","FALSA (respuesta): en Francia los cánceres son la 1.ª causa de muerte y las enfermedades cardiovasculares la 2.ª; el ictus es sobre todo la 1.ª causa de discapacidad, no de muerte."]],
  "70": ["La salud se reconoce como un derecho fundamental de todo ser humano. Ese reconocimiento implica que ese derecho se aplica:",["a toda persona, sean cuales sean su raza, su religión, su ideología o su condición económica y social","únicamente a las personas que ejercen un trabajo regular y cotizan a la protección social","a los individuos en función de su nivel de renta y de su cobertura de seguro","a los ciudadanos cuyo Estado ha inscrito expresamente ese derecho en su Constitución"],["El curso plantea la salud como un derecho fundamental de todo ser humano, sin distinción de raza, religión, ideología ni condición económica o social.","Falso: ese derecho es universal y no está subordinado al ejercicio de un trabajo ni a una cotización.","Falso: el derecho a la salud no depende ni de la renta ni de la cobertura de seguro de la persona.","Falso: se trata de un derecho humano fundamental de toda persona, no reservado a los nacionales de un Estado dado."]],
  "71": ["En el modelo tradicional, ¿cómo se define la salud?",["Como la sola ausencia de enfermedad, un estado normal del ser humano independiente de la cultura y de lo social","Como un estado de completo bienestar físico, mental y social que no se reduce a la ausencia de enfermedad","Como un recurso para la vida cotidiana que pone el acento en las capacidades personales y sociales","Como un continuo de grados variables que se extiende del bienestar hacia la pérdida de salud"],["El modelo tradicional define la salud como la ausencia de enfermedad, estado normal y natural independiente de la cultura y de los aspectos sociales.","Es la definición de la OMS (1946), que supera justamente el modelo tradicional al integrar el bienestar.","Es la concepción positiva (salud-recurso), posterior y opuesta al modelo tradicional.","Es el modelo del continuo, distinto de la visión dicotómica del modelo tradicional."]],
  "72": ["En la concepción de la salud como concepto positivo, esta se define como:",["un recurso para la vida cotidiana, y no el objetivo de la vida, que valora los recursos personales y sociales","el objetivo último de la vida, hacia el que deben tender el conjunto de los recursos personales y sociales","la ausencia de enfermedad o de discapacidad, considerada el estado normal y natural del individuo","un estado estrictamente biológico y estable, independiente de los recursos sociales y del contexto de vida"],["El concepto positivo hace de la salud un recurso para la vida cotidiana, no la finalidad de la vida, insistiendo en los recursos sociales y personales.","Invertido: la salud es un medio (un recurso), y no el objetivo de la vida.","Es la visión tradicional negativa, y no el concepto positivo de la salud.","El concepto positivo pone al contrario el acento en los recursos sociales y personales."]],
  "73": ["El concepto de salud y de enfermedad se describe con mayor exactitud como:",["dinámico y cambiante en función del contexto histórico, cultural y social","fijo y universal, idéntico sean cuales sean la época y el contexto cultural","estrictamente biológico, independiente de las dimensiones sociales y culturales","determinado únicamente por el contexto histórico, sin influencia cultural ni social"],["El curso presenta la salud y la enfermedad como un concepto dinámico que varía según el contexto histórico, cultural y social.","Falso: el concepto no es fijo, pues evoluciona según la época y el contexto.","Falso: las dimensiones sociales y culturales intervienen también en el concepto.","Incompleto: las dimensiones cultural y social también cuentan, no únicamente la historia."]],
  "74": ["Según el modelo del continuo salud-enfermedad, la salud y la enfermedad:",["forman un continuo con grados, sin ser estados que se excluyan mutuamente","constituyen dos estados dicotómicos y mutuamente excluyentes, sin estado intermedio","se suceden de forma cíclica, y una sustituye siempre bruscamente a la otra","coexisten permanentemente con una intensidad estrictamente igual en todo individuo"],["El modelo del continuo describe grados de salud y de enfermedad que no se excluyen mutuamente.","Es precisamente la visión dicotómica que el modelo del continuo refuta.","Falso: el paso se hace por grados progresivos y no por sustitución brusca.","Falso: los grados de salud y de enfermedad varían según los individuos y las situaciones."]],
  "75": ["¿Qué componente se añadió a la definición de la salud como estado de bienestar físico, mental y social?",["La capacidad funcional de la persona","La estabilidad emocional de la persona","El equilibrio homeostático del organismo","La longevidad y la esperanza de vida del individuo"],["La definición integra la capacidad funcional como componente de la salud, más allá de la ausencia de enfermedad.","Plausible, pero no es el componente que se añadió a esa definición de la salud.","Remite a la fisiología de la enfermedad y no al componente añadido a la salud.","La duración de la vida no es el componente añadido a la definición de la salud."]],
  "76": ["Un determinante de salud se define como:",["una característica individual o colectiva susceptible de influir directa o indirectamente en el estado de salud","una característica únicamente individual que influye solo de forma directa en el estado de salud","una intervención sanitaria destinada a restablecer directamente el estado de salud de una población","un indicador que mide a posteriori el nivel de salud alcanzado por una población"],["Es la definición del curso: característica individual o colectiva que actúa de forma directa o indirecta sobre el estado de salud.","Demasiado restrictivo: un determinante puede ser colectivo y actuar también de forma indirecta.","Confusión: una acción asistencial no es un determinante de salud.","Confusión: un indicador mide el estado de salud, no lo determina."]],
  "77": ["Los determinantes sociales de la salud, que explican la mayoría de las desigualdades de salud, corresponden:",["a las circunstancias en las que los individuos nacen, crecen, viven, trabajan y envejecen","a las características biológicas como la edad, el sexo y el patrimonio genético del individuo","a las prestaciones y a los servicios asistenciales que organiza el sistema sanitario de un territorio","a los comportamientos y estilos de vida personales que cada individuo adopta libremente"],["Son efectivamente las circunstancias de nacimiento, crecimiento, vida, trabajo y envejecimiento las que definen los determinantes sociales.","Son factores biológicos irreductibles, distintos de los determinantes sociales.","El sistema asistencial es un determinante por derecho propio, pero no son los determinantes sociales.","Los comportamientos corresponden a los estilos de vida individuales, no a los determinantes sociales."]],
  "78": ["El modelo de Lalonde agrupa los determinantes de la salud en cuatro grandes categorías. ¿Cuál de las proposiciones siguientes corresponde exactamente a esas cuatro categorías?",["Biología humana, medio ambiente, estilo de vida, sistema sanitario","Biología humana, medio ambiente, estilo de vida, nivel de renta","Biología humana, categoría social, estilo de vida, sistema sanitario","Herencia familiar, medio ambiente, estilo de vida, sistema sanitario"],["El modelo de Lalonde distingue precisamente esos cuatro campos: biología humana, medio ambiente, estilo de vida y sistema sanitario.","El nivel de renta no es uno de los cuatro campos; es el sistema sanitario el que constituye el cuarto grupo.","La categoría social no sustituye al medio ambiente, que figura por derecho propio entre los cuatro grupos.","La herencia familiar es demasiado restrictiva: Lalonde habla de biología humana, noción más amplia que la sola herencia."]],
  "79": ["En el modelo en capas (Dahlgren-Whitehead), ¿cómo se organizan los determinantes de la salud?",["En niveles (capas) superpuestos dispuestos alrededor de un núcleo de factores constitucionales","En cuatro sectores iguales repartidos alrededor de un núcleo de factores constitucionales","En una pirámide jerárquica cuya cima reúne los factores constitucionales","En una red de flechas que une cada determinante con el sistema sanitario"],["El modelo superpone capas de determinantes alrededor de un núcleo constitucional: es su estructura característica.","No se trata de sectores iguales, sino de capas concéntricas superpuestas.","El modelo no es una pirámide con niveles de cima y base: los determinantes se representan en capas.","El modelo apila capas alrededor de un núcleo; no une todo al sistema sanitario mediante una red."]],
  "80": ["En el modelo en capas, ¿qué determinantes constituyen el núcleo central?",["Los factores intrínsecos: sexo, edad y patrimonio genético","Los factores intrínsecos: sexo, renta y patrimonio genético","Los factores intrínsecos: sexo, edad y nivel educativo","Los factores intrínsecos: sexo, edad y condiciones de trabajo"],["El núcleo reúne los factores intrínsecos no modificables: sexo, edad y patrimonio genético.","La renta corresponde a las capas externas (condiciones socioeconómicas), no al núcleo intrínseco.","El nivel educativo es un determinante de las capas externas, no un factor constitucional del núcleo.","Las condiciones de trabajo pertenecen a las capas externas, no a los factores intrínsecos del núcleo."]],
  "81": ["La adopción de un estilo de vida saludable se presenta como dependiente de tres condiciones. ¿Cuáles?",["El «querer» (voluntad), el «saber» (conocimiento) y el «poder» (accesibilidad)","El «querer» (voluntad), el «saber» (conocimiento) y el «deber» (obligación)","El «querer» (motivación), el «creer» (convicción) y el «poder» (accesibilidad)","El «saber» (conocimiento), el «poder» (accesibilidad) y el «tener» (renta)"],["Adoptar un estilo de vida saludable supone querer (voluntad), saber (conocimiento) y poder (accesibilidad).","El «deber» no forma parte del tríptico; la tercera condición es el «poder» (accesibilidad).","El «creer» no figura en el tríptico, que se basa en el saber y no en la convicción.","El «tener» no sustituye al «querer»: la voluntad es una de las tres condiciones."]],
  "82": ["Entre los determinantes ambientales llamados biológicos se encuentran:",["Los virus, las bacterias, los hongos y el polen","Los virus, las bacterias, los hongos y el plomo","Los virus, las bacterias, el ruido y el polen","Los virus, los pesticidas, los hongos y el polen"],["Virus, bacterias, hongos y polen son agentes vivos: son determinantes biológicos.","El plomo es un determinante químico y no corresponde a los determinantes biológicos.","El ruido es un determinante físico, no biológico.","Los pesticidas son determinantes químicos, no agentes biológicos."]],
  "83": ["Entre los determinantes ambientales llamados físicos se encuentran:",["El ruido, la luz y la radiación ionizante","El ruido, la luz y los metales pesados","El ruido, el polen y la radiación ionizante","El ruido, la luz y los nitritos"],["Ruido, luz y radiación ionizante son agentes físicos: son determinantes físicos.","Los metales pesados son determinantes químicos, no físicos.","El polen es un agente biológico y no corresponde a los determinantes físicos.","Los nitritos son determinantes químicos, no físicos."]],
  "84": ["Entre los determinantes ambientales llamados químicos se encuentran:",["El mercurio, el plomo, el alquitrán y los pesticidas","El mercurio, el plomo, el alquitrán y el polen","El mercurio, el ruido, el alquitrán y los pesticidas","El mercurio, el plomo, el alquitrán y los virus"],["Mercurio, plomo, alquitrán y pesticidas son sustancias químicas: son determinantes químicos.","El polen es un agente biológico y no forma parte de los determinantes químicos.","El ruido es un determinante físico, no químico.","Los virus son agentes biológicos, no determinantes químicos."]],
  "85": ["El enfoque «One Health» (una sola salud) se basa en el vínculo entre:",["La salud humana, la salud animal y la salud ambiental","La salud humana, la salud animal y la salud económica","La salud humana, la salud mental y la salud ambiental","La salud humana, la salud animal y la salud digital"],["One Health articula salud humana, salud animal y salud ambiental como un conjunto indisociable.","La salud económica no forma parte del tríptico, que incluye la salud ambiental.","La salud mental no es uno de los tres pilares: One Health se dirige a la salud animal.","La salud digital no entra en One Health, que asocia la salud ambiental al trío."]],
  "86": ["¿Cómo califica la OMS el cambio climático desde el punto de vista de la salud?",["Como la mayor amenaza para la salud de la humanidad","Como un determinante ambiental menor entre otros","Como una amenaza sanitaria limitada a los países de rentas bajas","Como un riesgo secundario frente a las enfermedades transmisibles"],["El curso recoge la fórmula de la OMS: el cambio climático se presenta como la mayor amenaza para la salud de la humanidad.","Falso: no es menor, sino que se designa como la amenaza sanitaria mayor, con efectos sobre el agua, la alimentación y los vectores.","Falso: la amenaza es mundial; incluso agrava las desigualdades sanitarias y socioeconómicas entre poblaciones.","Falso: no es secundario, sino primero; favorece él mismo la transmisión de agentes patógenos y de zoonosis."]],
  "87": ["¿Qué describe el gradiente social de salud en cuanto al vínculo entre estatus socioeconómico y salud?",["Cuanto más bajo es el estatus socioeconómico, peor es el estado de salud","Cuanto más bajo es el estatus socioeconómico, mejor es el estado de salud","El estado de salud es independiente del estatus socioeconómico","Solo los individuos más pobres tienen un estado de salud deteriorado"],["Definición del gradiente: dentro de los países, cuanto más bajo es el estatus socioeconómico, peor es la salud; va de lo alto a lo bajo de la escala.","Falso: la relación es inversa; un estatus bajo se asocia a una peor salud, no a una mejor.","Falso: el estatus socioeconómico influye mucho en la salud, lo que es precisamente el objeto del gradiente social.","Falso: el gradiente es continuo a lo largo de toda la escala; las desigualdades afectan a todos, no solo a los más pobres."]],
  "88": ["¿Cuál es la extensión del gradiente social de salud según los datos presentados?",["Un fenómeno mundial, presente en rentas altas, medias y bajas","Un fenómeno limitado únicamente a los países de rentas bajas","Un fenómeno observado únicamente en los países de rentas altas","Un fenómeno propio de los países de rentas medias y bajas"],["El curso indica que se trata de un fenómeno mundial, observable en los países de rentas altas, medias y bajas.","Falso: no se limita a los países pobres; también se observa en rentas medias y altas.","Falso: no es propio de los países ricos; está presente en todos los niveles de renta.","Falso: los países de rentas altas también están afectados; el gradiente es mundial."]],
  "89": ["En Francia, ¿a qué parte de la población cubre el régimen general de la Seguridad Social?",["Alrededor del 90 % de la población","Alrededor del 60 % de la población","Alrededor del 75 % de la población","La totalidad de la población (100 %)"],["El régimen general, núcleo de la protección social francesa, cubre alrededor del 90 % de la población.","Falso: la cobertura es mucho más amplia, del orden del 90 %, y no del 60 %.","Falso: el régimen general cubre alrededor del 90 %, no el 75 %; otros regímenes lo completan.","Falso: no alcanza el 100 %; coexisten el régimen agrario y regímenes especiales."]],
  "90": ["¿Qué lista corresponde a las 6 ramas del régimen general de la Seguridad Social?",["Familia, Enfermedad, Accidentes de trabajo, Jubilación, Autonomía, Recaudación","Familia, Enfermedad, Desempleo, Jubilación, Autonomía, Recaudación","Familia, Enfermedad, Accidentes de trabajo, Jubilación, Autonomía, Vivienda","Familia, Enfermedad, Accidentes de trabajo, Jubilación, Dependencia, Recaudación"],["El régimen general comprende 6 ramas: Familia, Enfermedad, Accidentes de trabajo, Jubilación, Autonomía (CNSA) y Recaudación (Urssaf).","Falso: el desempleo corresponde a un dispositivo distinto; falta aquí la rama de Accidentes de trabajo y enfermedades profesionales.","Falso: la vivienda no es una rama del régimen general; la 6.ª rama es la Recaudación (Urssaf).","Falso: la rama ligada a la pérdida de autonomía se denomina oficialmente Autonomía (CNSA), y no «Dependencia»."]],
  "91": ["En relación con la Asignación Personalizada de Autonomía (APA), ¿qué proposición es correcta?",["Se dirige a las personas de al menos 60 años, a domicilio o en residencia","Se dirige a las personas de al menos 65 años, a domicilio o en residencia","Se dirige a las personas de al menos 60 años, únicamente a domicilio","Se dirige a las personas de cualquier edad en pérdida de autonomía, a domicilio"],["La APA se concede a las personas de al menos 60 años en pérdida de autonomía y existe en dos formas: APA a domicilio y APA en residencia.","Falso: el umbral de edad se fija en 60 años, y no en 65.","Falso: además de la APA a domicilio, existe una APA en residencia; no se limita al domicilio.","Falso: está reservada a las personas de al menos 60 años, y no a cualquier edad."]],
  "92": ["¿Cómo se define un indicador de salud?",["Una variable que mide y describe el estado de un problema de salud y su evolución","Una cifra absoluta recogida con independencia de la población estudiada","Una fuente de datos bruta recogida de forma continua por los registros","Una intervención destinada a reducir la magnitud de un problema de salud"],["Un indicador es una variable que mide y permite describir el estado de un problema de salud en una población, así como su evolución en el tiempo.","Falso: es la definición de un dato (valor absoluto); el indicador refiere ese dato a la población.","Falso: los registros son una fuente de datos; el indicador es la variable elaborada a partir de esas fuentes.","Falso: el indicador mide y describe un problema; no actúa sobre él, al contrario que una intervención."]],
  "93": ["¿Qué representa un «dato» frente a un indicador de salud?",["Una cifra en valor absoluto, poco informativa si no se refiere a la población","Una tasa que refiere un evento al tamaño de la población estudiada","Una variable que describe la evolución de un problema de salud en el tiempo","Una medida que combina mortalidad y calidad de vida relacionada con la salud"],["Un dato es una cifra en valor absoluto; sin referirse a la población estudiada, no informa sobre la importancia relativa del problema.","Falso: la tasa (evento referido a la población) corresponde al indicador, no al dato bruto.","Falso: describir la evolución de un problema es el papel del indicador; el dato es solo una cifra absoluta.","Falso: combinar mortalidad y calidad de vida define un indicador sintético (AVAD/AVAC), no un dato."]],
  "94": ["¿Cómo se define una tasa en epidemiología?",["La aparición de un evento en un periodo, referida al tamaño de la población estudiada.","La relación entre dos efectivos independientes procedentes de poblaciones eventualmente distintas.","La parte de los individuos que presentan una característica en un grupo, en un instante dado.","La relación entre el número de sujetos expuestos y el número de sujetos no expuestos."],["Definición exacta de la tasa: número de eventos ocurridos durante un periodo, referido al efectivo de la población.","Describe una razón, que compara dos efectivos independientes, y no una tasa.","Describe una proporción medida en un instante, sin la dimensión de aparición durante un periodo propia de la tasa.","Describe una odds de exposición, y no una tasa referida a la población."]],
  "95": ["¿Qué característica define la recogida de datos mediante registros administrativos?",["Una recogida continua y sistemática, basada en el conjunto de la población (nacimientos, fallecimientos, cánceres).","Una recogida activa pero intermitente, realizada sobre muestras representativas de la población.","Una recogida pasiva cuya representatividad de la población no está garantizada.","Una recogida puntual y dirigida, limitada únicamente a los sujetos voluntarios de una población."],["Los registros administrativos recogen de forma continua y sistemática, a escala de toda la población.","Describe las encuestas de salud, activas pero periódicas y realizadas sobre una muestra, no los registros.","Describe los sistemas de notificación, pasivos y de representatividad incierta, no los registros.","No corresponde a los registros, que son continuos y exhaustivos y no se limitan a los voluntarios."]],
  "96": ["¿Qué caracteriza a las encuestas de salud como modo de recogida de datos?",["Una recogida activa pero intermitente, realizada sobre muestras representativas de la población.","Una recogida continua y sistemática sobre el conjunto de la población estudiada.","Una recogida pasiva cuya representatividad de la población no está asegurada.","Una recogida continua y voluntaria limitada únicamente a los centros asistenciales declarantes."],["Las encuestas de salud son activas, periódicas y se realizan sobre muestras representativas.","Describe los registros administrativos, continuos y exhaustivos, no las encuestas de salud.","Describe los sistemas de notificación, pasivos y de representatividad no garantizada, no las encuestas.","No corresponde a las encuestas, que se basan en una muestra representativa y no en declarantes."]],
  "97": ["¿Qué caracteriza a los sistemas de notificación?",["Una recogida pasiva cuya representatividad de la población no está garantizada.","Una recogida continua y sistemática basada en el conjunto de la población estudiada.","Una recogida activa pero periódica, realizada sobre muestras representativas de la población.","Una recogida activa y exhaustiva que garantiza la representatividad de la población."],["Los sistemas de notificación se basan en una declaración pasiva, sin representatividad asegurada.","Describe los registros administrativos, continuos y exhaustivos, no la notificación.","Describe las encuestas de salud, activas e intermitentes sobre muestra, no la notificación.","Falso: la notificación es pasiva y precisamente no garantiza la representatividad."]],
  "98": ["¿Qué indicador es el más utilizado para comparar la mortalidad entre distintas poblaciones?",["La esperanza de vida al nacer.","La tasa de mortalidad infantil.","La tasa de mortalidad materna.","La tasa de letalidad hospitalaria."],["Es el indicador más utilizado para comparar la mortalidad entre poblaciones.","Indicador de mortalidad, pero no el que se señala como el más utilizado para la comparación global.","Indicador de mortalidad específico, no considerado el más utilizado para comparar poblaciones.","Mide la gravedad de una enfermedad, no la comparación de mortalidad entre poblaciones."]],
  "99": ["¿Qué miden los AVAD?",["Las pérdidas de salud debidas a la mortalidad y a la discapacidad prematuras.","Las ganancias de salud de una intervención, en duración y en calidad de vida.","La parte de la población con una discapacidad en un momento dado.","Los años de vida ganados gracias a las acciones de prevención primaria."],["Los AVAD cuantifican las pérdidas de salud (mortalidad + discapacidad), es decir la carga de la enfermedad.","Describe los AVAC (ganancia de salud de una intervención), no los AVAD.","Describe una prevalencia de discapacidad, no la medida de una carga mediante los AVAD.","Describe un beneficio de prevención, no las pérdidas de salud que miden los AVAD."]],
  "100": ["¿Qué miden los AVAC?",["La ganancia de salud de una intervención, combinando duración y calidad de vida.","Las pérdidas de salud debidas a la mortalidad y a la discapacidad prematuras.","El coste medio de una intervención referido al número de pacientes tratados.","El número de eventos de salud evitados por una campaña de cribado."],["Los AVAC miden la ganancia de salud de una intervención asociando duración y calidad de vida.","Describe los AVAD (pérdidas de salud), no los AVAC.","Describe un indicador de coste, no la ganancia de salud que miden los AVAC.","Describe eventos evitados, no la ganancia en años ponderados por la calidad de vida."]],
  "101": ["¿Qué elemento es común a todas las definiciones de la salud pública?",["El acento puesto en la prevención y la promoción de la salud.","La prioridad dada al tratamiento curativo de los casos individuales.","La centralización de la asistencia en los centros hospitalarios.","La especialización de las intervenciones según la patología a la que se dirigen."],["La prevención y la promoción figuran entre los tres elementos comunes a todas las definiciones.","A la inversa: la salud pública privilegia el enfoque colectivo y la prevención, no lo curativo individual.","La salud pública actúa a escala de las poblaciones, no mediante centralización hospitalaria.","La salud pública adopta un enfoque colectivo de las poblaciones, no una especialización por patología."]],
  "102": ["En salud pública, ¿a quién corresponde la organización de las intervenciones que mejoran la salud de la población, y cuál es su carácter?",["A los servicios sanitarios, que organizan solos las intervenciones; es monodisciplinar y monoinstitucional.","A los gobiernos, a quienes corresponde organizar las intervenciones; es multidisciplinar y multiinstitucional.","A los profesionales liberales, que organizan las intervenciones; es pluriprofesional pero monoinstitucional.","A las entidades locales, que organizan las intervenciones; es multidisciplinar pero monoinstitucional."],["Los servicios sanitarios solo llevan a cabo ciertas actividades (prevención, restablecimiento), sin asumir solos esa responsabilidad.","El curso atribuye la salud pública a los gobiernos y la califica de multidisciplinar y multiinstitucional.","La responsabilidad corresponde a los gobiernos, no a los profesionales liberales, y el carácter es multiinstitucional.","La responsabilidad corresponde a los gobiernos y el carácter es multiinstitucional, no monoinstitucional."]],
  "103": ["¿En qué orden se encadenan las etapas del ciclo de la salud pública?",["Conocer el estado de salud → identificar un problema → analizar los determinantes → intervenir → analizar el impacto.","Conocer el estado de salud → identificar un problema → intervenir → analizar los determinantes → analizar el impacto.","Analizar los determinantes → identificar un problema → conocer el estado de salud → intervenir → analizar el impacto.","Identificar un problema → analizar los determinantes → conocer el estado de salud → analizar el impacto → intervenir."],["Tema 1.2 p.9, repetido igual en el tema 1.3 p.16: «Conocer el estado de salud de la población → Identificar un problema de salud → Analizar los determinantes del problema → Realizar una intervención → Analizar el impacto de la intervención». Se parte, por tanto, del estado de salud, no del problema.","El punto de partida es correcto, pero la intervención llega DESPUÉS del análisis de los determinantes (tema 1.2 p.9): no se puede actuar antes de haber identificado sobre qué actuar.","Orden imposible: los determinantes se analizan una vez identificado el problema, que a su vez se detecta a partir del estado de salud de la población (tema 1.2 p.9).","Dos errores: el conocimiento del estado de salud va primero, y el análisis del impacto cierra el ciclo, después de la intervención (tema 1.2 p.9)."]],
  "104": ["¿Qué abarca la vigilancia en salud pública?",["Recoger, almacenar, facturar y archivar información sobre el estado de salud y sus factores.","Prescribir, analizar, interpretar y difundir información sobre el estado de salud y sus factores.","Recoger, analizar, interpretar y difundir información sobre el estado de salud y sus factores.","Recoger, analizar, interpretar y ocultar información sobre el estado de salud y sus factores."],["La vigilancia interpreta y difunde la información; no se limita a almacenarla y archivarla.","La vigilancia recoge la información de partida; no la «prescribe».","Son las cuatro actividades de la definición, al servicio de las acciones de salud pública.","La finalidad es difundir la información para apoyar la acción, no ocultarla."]],
  "105": ["¿A qué corresponden los tres ejes de Salud Pública Francia?",["Anticipar (prevención y promoción), comprender (alerta y vigilancia), actuar (conocimiento del estado de salud).","Anticipar (alerta y vigilancia), comprender (conocimiento del estado de salud), actuar (prevención, promoción y crisis).","Anticipar (respuesta a las crisis), comprender (prevención y promoción), actuar (alerta y vigilancia).","Anticipar (conocimiento del estado de salud), comprender (respuesta a las crisis), actuar (alerta y vigilancia)."],["La alerta y la vigilancia corresponden a anticipar, no a comprender.","Es el emparejamiento de los tres ejes tal como los define la agencia.","La respuesta a las crisis corresponde a actuar, y la alerta y la vigilancia a anticipar.","El conocimiento del estado de salud corresponde a comprender, no a anticipar."]],
  "106": ["¿Cuál es el papel de la Unión Europea en materia de salud?",["Sustituir las políticas nacionales, de modo que la organización asistencial pasa a ser responsabilidad de la UE.","Armonizar las políticas nacionales, de modo que la organización asistencial pasa a ser una competencia compartida UE-Estados.","Completar las políticas nacionales, de modo que la organización asistencial pasa a ser responsabilidad de la UE.","Completar las políticas nacionales, de modo que la organización asistencial sigue siendo responsabilidad de los Estados miembros."],["La UE no sustituye las políticas nacionales y la organización asistencial sigue correspondiendo a los Estados.","El papel es completar, no armonizar, y la asistencia corresponde únicamente a los Estados miembros.","El primer término es exacto, pero la organización asistencial sigue siendo de los Estados, no de la UE.","La UE completa las políticas nacionales, y la organización asistencial sigue correspondiendo a los Estados miembros."]],
  "107": ["¿Qué papel ocupa la OMS en el sistema de las Naciones Unidas?",["La autoridad de gestión y de coordinación de la acción sanitaria dentro del sistema de las Naciones Unidas.","La autoridad de gestión y de coordinación de la ayuda alimentaria dentro del sistema de las Naciones Unidas.","La autoridad de financiación y de facturación de la acción sanitaria dentro del sistema de las Naciones Unidas.","La autoridad de control y de sanción de la acción sanitaria dentro del sistema de las Naciones Unidas."],["Es exactamente el papel que se atribuye a la OMS en el sistema de la ONU.","La OMS coordina la acción sanitaria, no la ayuda alimentaria.","Su papel es la gestión y la coordinación, no la financiación y la facturación.","La OMS gestiona y coordina la acción sanitaria; no «sanciona»."]],
  "108": ["¿Cuál es la naturaleza y el objetivo del Reglamento Sanitario Internacional (RSI)?",["Instrumento jurídico facultativo dirigido a evitar la propagación internacional de las enfermedades sin traba innecesaria al comercio.","Recomendación no vinculante dirigida a limitar las enfermedades priorizando el cierre del tráfico y del comercio.","Instrumento jurídico obligatorio dirigido a evitar la propagación internacional de las enfermedades sin traba innecesaria al comercio.","Instrumento jurídico obligatorio dirigido a suspender sistemáticamente el tráfico y el comercio en caso de enfermedad transfronteriza."],["El RSI es un instrumento obligatorio, no facultativo.","El RSI es vinculante y busca al contrario evitar las trabas innecesarias al comercio.","El RSI es obligatorio y busca contener las enfermedades sin obstaculizar innecesariamente el tráfico y el comercio.","El RSI busca precisamente evitar las trabas innecesarias, no suspender sistemáticamente los intercambios."]],
  "109": ["¿Cómo se define una Emergencia de Salud Pública de Importancia Internacional (ESPII)?",["Un evento habitual y localizado, sin implicación transfronteriza, que corresponde a una acción estrictamente nacional.","Un evento extraordinario y grave, con implicaciones transfronterizas, que puede requerir una acción internacional coordinada.","Un evento extraordinario y grave, sin implicación transfronteriza, que corresponde a una acción estrictamente nacional.","Un evento habitual y esperado, con implicaciones transfronterizas, que puede requerir una acción internacional coordinada."],["Una ESPII es al contrario extraordinaria y supera las fronteras del Estado afectado.","Es la definición establecida: evento extraordinario, transfronterizo, que exige una respuesta coordinada.","La ESPII implica un riesgo de propagación que supera las fronteras nacionales.","Una ESPII es extraordinaria, súbita o inesperada, no un evento habitual y esperado."]],
  "110": ["En virtud del Reglamento Sanitario Internacional (RSI), ¿quién declara en última instancia una emergencia de salud pública de importancia internacional (ESPII)?",["El Director General de la OMS, previo dictamen del Comité de Emergencia del RSI.","El Comité de Emergencia del RSI, a propuesta del Director General de la OMS.","La Asamblea Mundial de la Salud, previo dictamen del Director General de la OMS.","El Estado afectado, tras notificarlo al Director General de la OMS."],["Es efectivamente el Director General de la OMS quien declara en última instancia la ESPII, pues el Comité de Emergencia solo emite un dictamen técnico.","El Comité de Emergencia solo emite un dictamen técnico; no declara él mismo la ESPII.","La Asamblea Mundial de la Salud no interviene en esa declaración, que corresponde al Director General.","El Estado afectado notifica el evento, pero no declara la ESPII; esa responsabilidad corresponde al Director General."]],
  "111": ["Entre las proposiciones siguientes, ¿cuál corresponde a la definición de la demografía?",["La ciencia que estudia de forma cuantitativa y cualitativa las poblaciones humanas (tamaño, estructura, evolución).","La ciencia que estudia la distribución y los determinantes de las enfermedades en las poblaciones humanas.","La ciencia que estudia únicamente los movimientos migratorios y el saldo migratorio de las poblaciones.","La ciencia que estudia la asociación entre los factores de riesgo y la aparición de las enfermedades."],["La demografía es efectivamente el estudio cuantitativo y cualitativo de las poblaciones, de su tamaño, su estructura y su evolución.","Esa formulación corresponde a la epidemiología, y no a la demografía.","Las migraciones son solo una dimensión; la demografía abarca también el tamaño, la estructura y la evolución.","El estudio de la asociación entre factores de riesgo y enfermedad corresponde a la epidemiología analítica, no a la demografía."]],
  "112": ["¿Cómo reparte tradicionalmente la pirámide de población a la población?",["Por sexo (hombres a la izquierda, mujeres a la derecha) y por edad en tramos de 5 años.","Por sexo (mujeres a la izquierda, hombres a la derecha) y por edad en tramos de 5 años.","Por sexo (hombres a la izquierda, mujeres a la derecha) y por edad en tramos de 10 años.","Por estado civil (solteros a la izquierda, casados a la derecha) y por edad en tramos de 5 años."],["Tradicionalmente los hombres figuran a la izquierda y las mujeres a la derecha, con tramos de edad de 5 años.","La orientación está invertida: los hombres se colocan a la izquierda y las mujeres a la derecha.","Los tramos de edad que se emplean son generalmente de 5 años, y no de 10.","El reparto lateral se hace por sexo, no por estado civil."]],
  "113": ["¿Qué relación existe entre la tasa de natalidad y la forma de la pirámide de población?",["Cuanto más elevada es la tasa de natalidad, más ancha es la base de la pirámide.","Cuanto más elevada es la tasa de natalidad, más estrecha es la base de la pirámide.","Cuanto más elevada es la tasa de natalidad, más se ensancha la cima de la pirámide.","Cuanto más baja es la tasa de natalidad, más ancha es la base de la pirámide."],["La base representa a los más jóvenes: una tasa de natalidad elevada la ensancha.","Una tasa de natalidad elevada ensancha la base en lugar de estrecharla.","La natalidad actúa sobre la base (los jóvenes), no sobre la cima, que corresponde a las edades avanzadas.","Es al revés: una tasa de natalidad baja da una base estrecha."]],
  "114": ["¿A qué tipo de población corresponde una pirámide de población en forma de pirámide (o pagoda), de base ancha?",["Una población joven, en expansión.","Una población envejecida, en decrecimiento.","Una población estacionaria, con natalidad en descenso.","Una población equilibrada, con una esperanza de vida muy elevada."],["Una base ancha traduce una natalidad elevada y, por tanto, una población joven y en expansión.","Una población en decrecimiento corresponde a una base estrecha (peonza), no a una base ancha.","Una población estacionaria corresponde a la forma de campana, no a la base ancha.","Una esperanza de vida muy elevada estira la cima (peonza); la base ancha traduce la juventud."]],
  "115": ["La pirámide de población en forma de campana, de base menos ancha y que se estira hacia arriba, corresponde a:",["Una población estacionaria.","Una población en fuerte expansión.","Una población en claro decrecimiento.","Una población muy joven."],["La forma de campana (natalidad que empieza a bajar, esperanza de vida que aumenta) traduce una población estacionaria.","La expansión corresponde a la forma de pirámide o pagoda, de base ancha.","El decrecimiento corresponde a la forma de peonza, de base estrecha.","Una población muy joven da una base ancha, no una forma de campana."]],
  "116": ["Una pirámide de población en forma de peonza, de base estrecha y muy estirada hacia arriba, corresponde a:",["Una población en decrecimiento.","Una población estacionaria.","Una población en expansión.","Una población joven con natalidad elevada."],["Una base estrecha (natalidad muy baja) y una cima estirada (esperanza de vida elevada) caracterizan a una población en decrecimiento.","La población estacionaria corresponde a la forma de campana.","La expansión corresponde a la forma de pirámide o pagoda, de base ancha.","Una natalidad elevada ensancharía la base; la peonza presenta al contrario una base estrecha."]],
  "117": ["¿Cómo se calcula el saldo natural de una población en un periodo dado?",["Diferencia entre el número de nacimientos y el número de fallecimientos.","Diferencia entre el número de entradas y el número de salidas del territorio.","Suma del saldo natural y del saldo migratorio del año.","Diferencia entre el número de nacimientos y el número de inmigrantes."],["El saldo natural = nacimientos − fallecimientos; es positivo cuando los nacimientos superan a los fallecimientos.","Eso define el saldo migratorio, y no el saldo natural.","Esa suma corresponde al crecimiento absoluto de la población, no al saldo natural.","El saldo natural opone nacimientos y fallecimientos; no integra ningún dato migratorio."]],
  "118": ["Elija la respuesta CORRECTA. El saldo migratorio de un territorio corresponde, en un periodo dado, a:",["la diferencia entre las personas que han entrado en el territorio y las que han salido de él","la diferencia entre los nacimientos y los fallecimientos registrados en el territorio","la suma de las personas que han entrado en el territorio y de las que han salido de él","la diferencia entre las personas que han entrado en el territorio y los nacimientos registrados"],["Exacto: el saldo migratorio opone las entradas a las salidas del territorio durante el periodo.","Falso: esa diferencia nacimientos − fallecimientos define el saldo natural, no el saldo migratorio.","Falso: se restan las salidas a las entradas, no se suman.","Falso: el saldo migratorio opone entradas y salidas, y no hace intervenir los nacimientos."]],
  "119": ["Elija la respuesta CORRECTA. El crecimiento absoluto de la población en un año se obtiene:",["sumando el saldo natural y el saldo migratorio del año","restando el saldo migratorio al saldo natural del año","sumando el número de nacimientos y el número de entradas en el territorio","restando el saldo natural al saldo migratorio del año"],["Exacto: crecimiento absoluto = saldo natural + saldo migratorio.","Falso: los dos saldos se suman, no se restan.","Falso: cada término es un saldo (una diferencia), no una simple suma de nacimientos y entradas.","Falso: se trata de una suma de los dos saldos, no de una diferencia entre ellos."]],
  "120": ["Elija la respuesta CORRECTA. La tasa bruta de natalidad se calcula refiriendo:",["el número de nacidos vivos a la población total, multiplicado por 1000","el número de nacidos vivos al número total de fallecimientos, multiplicado por 1000","el número de nacidos vivos al número de mujeres en edad fértil, multiplicado por 1000","el número de fallecimientos de menores de un año a la población total, multiplicado por 1000"],["Exacto: tasa bruta de natalidad = (nacidos vivos / población total) × 1000.","Falso: referir los nacimientos a los fallecimientos no corresponde a ninguna tasa bruta de natalidad.","Falso: el denominador es la población total, no solo las mujeres fértiles.","Falso: ese numerador remite a la mortalidad, no a la natalidad."]],
  "121": ["Elija la respuesta CORRECTA. En los países desarrollados, el nivel de reemplazo generacional se alcanza cuando el índice coyuntural de fecundidad se aproxima a:",["2,1 hijos por mujer","1,5 hijos por mujer","2,5 hijos por mujer","3,0 hijos por mujer"],["Exacto: el umbral de reemplazo generacional se estima en alrededor de 2,1 hijos por mujer.","Falso: 1,5 traduce una fecundidad baja, por debajo del umbral de reemplazo.","Falso: 2,5 supera el umbral de reemplazo de los países desarrollados.","Falso: 3,0 corresponde a una fecundidad elevada, muy por encima del umbral."]],
  "122": ["Elija la respuesta CORRECTA a propósito de la tasa bruta de mortalidad:",["corresponde a (fallecimientos / población total) × 1000 y no indica por sí sola el estado sanitario del país","corresponde a (fallecimientos / población total) × 1000 y traduce directamente el estado sanitario del país","corresponde a (fallecimientos de menores de un año / nacimientos) × 1000 y traduce las condiciones socioeconómicas","corresponde a (fallecimientos / población total) × 1000 y no puede desglosarse ni por edad ni por causa"],["Exacto: es efectivamente esa relación, y no informa por sí sola sobre la situación sanitaria.","Falso: esa tasa no refleja directamente la situación sanitaria de un país.","Falso: esa definición es la de la tasa de mortalidad infantil.","Falso: esa tasa puede al contrario calcularse por edad o por causa de muerte."]],
  "123": ["Elija la respuesta CORRECTA. La tasa de mortalidad infantil:",["refiere los fallecimientos de menores de un año a los nacidos vivos e informa sobre las condiciones socioeconómicas","refiere los fallecimientos de menores de un año a la población total e informa sobre las condiciones socioeconómicas","refiere los fallecimientos de menores de un año a los nacidos vivos, pero no guarda relación con las condiciones socioeconómicas","refiere los fallecimientos ocurridos antes de los 65 años a los nacidos vivos e informa sobre las condiciones socioeconómicas"],["Exacto: (fallecimientos de menores de un año / nacidos vivos) × 1000, indicador de las condiciones socioeconómicas.","Falso: el denominador es el número de nacidos vivos, no la población total.","Falso: ese indicador refleja justamente las condiciones socioeconómicas del país.","Falso: el umbral de los 65 años concierne a la mortalidad prematura, no a la mortalidad infantil."]],
  "124": ["Elija la respuesta CORRECTA a propósito de la mortalidad prematura:",["aparece antes de la edad media de fallecimiento, genera años potenciales de vida perdidos y podría teóricamente evitarse","aparece después de la edad media de fallecimiento, genera años potenciales de vida perdidos y podría teóricamente evitarse","aparece antes de la edad media de fallecimiento, no genera años de vida perdidos y podría teóricamente evitarse","aparece antes de la edad media de fallecimiento, genera años potenciales de vida perdidos, pero es por naturaleza inevitable"],["Exacto: al aparecer antes de la edad media de fallecimiento, ocasiona años potenciales de vida perdidos y es teóricamente evitable.","Falso: aparece antes, y no después, de la edad media de fallecimiento de la población.","Falso: es precisamente ella la que provoca años potenciales de vida perdidos.","Falso: esa mortalidad se describe como teóricamente evitable."]],
  "125": ["Elija la respuesta CORRECTA. La incidencia de una enfermedad corresponde:",["al número de casos nuevos que aparecen en un periodo en una población en riesgo, y mide el ritmo de aparición","al número total de casos, antiguos y nuevos, presentes en la población en un momento dado","al número de casos nuevos que aparecen en un periodo referido al número de fallecimientos por la enfermedad","al número de casos curados en un periodo en una población en riesgo, y mide el ritmo de curación"],["Exacto: la incidencia cuenta los casos nuevos en un periodo en una población en riesgo y mide el ritmo de aparición.","Falso: el recuento de casos antiguos y nuevos en un instante dado define la prevalencia.","Falso: la incidencia refiere los casos nuevos a la población en riesgo, no al número de fallecimientos.","Falso: la incidencia cuenta los casos nuevos de enfermedad, no las curaciones."]],
  "126": ["Según el curso, la incidencia de una enfermedad se obtiene en estudios que comportan:",["Un seguimiento de la población durante un periodo de observación definido","Una medición puntual de la situación en un momento dado","Un recuento de todos los casos presentes en un instante dado","Una observación transversal realizada sin ningún seguimiento"],["Correcto: la incidencia se obtiene en los estudios epidemiológicos con seguimiento (periodo de observación).","Falso: una medición en un instante preciso, sin seguimiento, corresponde a la prevalencia.","Falso: contar todos los casos presentes en un instante remite a la prevalencia, no a la incidencia.","Falso: los estudios transversales sin seguimiento miden la prevalencia."]],
  "127": ["¿Para qué tipo de enfermedades se utiliza particularmente la medición de la incidencia?",["Las enfermedades de periodo clínico corto, como las infecciones o el infarto","Las enfermedades crónicas de evolución lenta, como la diabetes o la artrosis","Las enfermedades incurables de larga duración con baja letalidad","Las características estables de la población, como el tabaquismo"],["Correcto: la incidencia sirve para las enfermedades de periodo clínico corto (infecciosas, infarto).","Falso: esas enfermedades crónicas de evolución lenta corresponden más bien a la prevalencia.","Falso: las enfermedades de larga duración se describen mejor con la prevalencia.","Falso: medir un factor de riesgo como el tabaquismo corresponde a la prevalencia."]],
  "128": ["¿Qué representa la prevalencia de una enfermedad en una población?",["El número total de casos, antiguos y nuevos, presentes en un momento dado","El número de casos nuevos aparecidos durante un periodo dado","El número de casos nuevos referido a la población en riesgo","El número de casos curados o fallecidos durante un periodo"],["Correcto: la prevalencia cuenta todos los casos (antiguos + nuevos) en un momento dado; es un valor estático.","Falso: contar solo los casos nuevos en un periodo define la incidencia.","Falso: referir los casos nuevos a la población en riesgo corresponde a la incidencia.","Falso: las salidas por curación o fallecimiento no definen la prevalencia."]],
  "129": ["¿Para qué tipo de enfermedades se utiliza particularmente la medición de la prevalencia?",["Las enfermedades crónicas o de evolución lenta, como la diabetes o la artrosis","Las enfermedades de periodo clínico corto, como las infecciones agudas","Los eventos agudos y súbitos, como el infarto","Las epidemias infecciosas de propagación rápida en la población"],["Correcto: la prevalencia sirve para las enfermedades crónicas o de evolución lenta (diabetes, artrosis).","Falso: las enfermedades de periodo clínico corto corresponden a la incidencia.","Falso: un evento agudo como el infarto se mide con la incidencia.","Falso: la aparición rápida de casos nuevos infecciosos se mide con la incidencia."]],
  "130": ["En una población estable y cuando la prevalencia es baja, ¿qué relación une esas tres magnitudes?",["Prevalencia = Incidencia × Duración de la enfermedad","Incidencia = Prevalencia × Duración de la enfermedad","Prevalencia = Incidencia ÷ Duración de la enfermedad","Duración = Prevalencia × Incidencia de la enfermedad"],["Correcto: en esas condiciones, P = I × D (prevalencia = incidencia × duración).","Falso: es la prevalencia, y no la incidencia, la que es ese producto.","Falso: la relación es un producto, no una división.","Falso: la duración no es el producto de la prevalencia y de la incidencia."]],
  "131": ["En una población, una prevalencia elevada puede traducir:",["Una incidencia elevada o una enfermedad de larga duración","Una incidencia baja o una curación rápida de los enfermos","Una incidencia baja o un fallecimiento rápido de los enfermos","Una incidencia baja o una enfermedad de corta duración"],["Correcto: una prevalencia elevada traduce una incidencia elevada o una enfermedad de larga duración.","Falso: una incidencia baja y una desaparición rápida corresponden a una prevalencia baja.","Falso: una desaparición rápida por fallecimiento reduce la prevalencia.","Falso: una incidencia baja y una corta duración reducen la prevalencia."]],
  "132": ["En una población, una prevalencia baja puede traducir:",["Una incidencia baja o una desaparición rápida de los casos","Una incidencia elevada o una enfermedad de larga duración","Una incidencia elevada o una baja letalidad de la enfermedad","Una larga duración de la enfermedad con pocas curaciones"],["Correcto: una prevalencia baja traduce una incidencia baja o una desaparición rápida (curación o fallecimiento).","Falso: una incidencia elevada y una larga duración corresponden a una prevalencia elevada.","Falso: una incidencia elevada y una supervivencia larga aumentan la prevalencia.","Falso: una larga duración aumenta la prevalencia, no la reduce."]],
  "133": ["¿Qué permiten establecer los estudios observacionales?",["La relación entre una exposición (factor de riesgo) y un evento","El efecto de una intervención aplicada deliberadamente por el investigador","La sola distribución de las enfermedades, sin buscar ninguna exposición","Un vínculo de causa a efecto probado de forma segura y definitiva"],["Correcto: los estudios observacionales establecen la relación exposición (factor de riesgo) → evento.","Falso: aplicar una intervención corresponde a los estudios experimentales o de intervención.","Falso: describir solo la distribución corresponde a la epidemiología descriptiva.","Falso: una asociación observada no prueba por sí sola la causalidad."]],
  "134": ["En epidemiología, ¿cuál es el objetivo principal de un estudio descriptivo?",["Describir la frecuencia y la distribución de los fenómenos de salud en la población","Analizar las relaciones de causa a efecto entre dos fenómenos de salud","Evaluar los efectos de las intervenciones realizadas para mejorar la salud","Cuantificar la fuerza de la asociación entre una exposición y una enfermedad"],["La epidemiología descriptiva describe frecuencia y distribución respondiendo a dónde, cuándo, quién y cómo.","Es el objetivo de la epidemiología analítica (pregunta «por qué»), no de la descriptiva.","Es el objetivo de la epidemiología evaluativa o de intervención.","Cuantificar la asociación (RR, OR) corresponde al enfoque analítico, no al descriptivo."]],
  "135": ["Un equipo busca comprender por qué algunas personas enferman, estudiando el vínculo entre una exposición y una enfermedad. ¿A qué tipo de estudio epidemiológico corresponde ese enfoque?",["El estudio analítico","El estudio descriptivo","El estudio de intervención","El estudio transversal"],["Busca las relaciones de causa a efecto entre exposición y enfermedad («por qué»).","Describe la frecuencia y la distribución de las enfermedades, sin buscar su causa.","Evalúa los efectos de una intervención, no el vínculo causal exposición-enfermedad.","Mide la prevalencia en un instante dado; es un enfoque descriptivo."]],
  "136": ["¿Qué tipo de estudio epidemiológico tiene como finalidad evaluar los efectos de las intervenciones realizadas para mejorar el estado de salud de una población?",["El estudio evaluativo","El estudio descriptivo","El estudio analítico","El estudio de cohortes"],["La epidemiología evaluativa o de intervención estudia los efectos de las intervenciones de salud.","Describe la frecuencia y la distribución de los fenómenos de salud.","Busca las relaciones de causa a efecto entre dos fenómenos («por qué»).","Estudio observacional del vínculo exposición-enfermedad, no la evaluación de una intervención."]],
  "137": ["En teoría de la causalidad, ¿qué puede afirmarse cuando se constata una asociación entre dos fenómenos de salud?",["No corresponde necesariamente a una verdadera relación de causa a efecto","Prueba siempre la existencia de una verdadera relación de causa a efecto","Excluye todo papel posible de un factor de riesgo común a ambos","Establece de entrada la secuencia temporal entre los dos fenómenos"],["No toda asociación observada es causal; puede no serlo.","Falso: una asociación no prueba por sí sola la causalidad.","Falso: una asociación no excluye la intervención de un factor de riesgo.","Falso: la asociación no informa sobre la anterioridad de la causa."]],
  "138": ["Para establecer una relación causal entre una exposición y una enfermedad, ¿qué condición relativa a la secuencia temporal debe respetarse?",["La causa debe preceder siempre al efecto en el tiempo","El efecto debe preceder siempre a la causa en el tiempo","La causa y el efecto deben aparecer en el mismo momento","El orden de aparición de la causa y del efecto es indiferente"],["Criterio absoluto: la secuencia temporal impone que la causa preceda al efecto.","Inversión incorrecta: el efecto no puede preceder a su causa.","La simultaneidad no satisface el criterio de anterioridad de la causa.","Falso: la secuencia temporal es indispensable para afirmar la causalidad."]],
  "139": ["En el modelo probabilístico de la causalidad, ¿cómo se define un factor de riesgo respecto de la aparición de la enfermedad?",["No es ni necesario ni suficiente para que la enfermedad aparezca","Es a la vez necesario y suficiente para que la enfermedad aparezca","Es necesario pero no suficiente para que la enfermedad aparezca","Es suficiente pero no necesario para que la enfermedad aparezca"],["Definición del factor de riesgo: aumenta la probabilidad sin ser necesario ni suficiente.","Sería una causa determinista, no un factor de riesgo probabilístico.","Un factor de riesgo no es necesario: la enfermedad puede aparecer sin él.","Un factor de riesgo no es suficiente: solo aumenta la probabilidad."]],
  "140": ["El carácter multicausal del modelo probabilístico, ilustrado por las enfermedades cardiovasculares, significa que:",["Una misma enfermedad puede resultar de varios factores de riesgo","Un mismo factor de riesgo puede provocar varias enfermedades","Una misma enfermedad solo depende de un único factor de riesgo","Un mismo factor de riesgo nunca produce más que una sola enfermedad"],["Multicausalidad: una enfermedad tiene varios factores de riesgo (tabaco, HTA, diabetes...).","Eso describe la multiplicidad del efecto, no la multicausalidad.","Contrario al carácter multicausal del modelo probabilístico.","Afirmación falsa que no describe la multicausalidad."]],
  "141": ["La multiplicidad del efecto en el modelo probabilístico, ilustrada por el tabaquismo, corresponde al hecho de que:",["Un mismo factor de riesgo puede estar implicado en varias enfermedades","Una misma enfermedad puede estar causada por varios factores de riesgo","Un mismo factor de riesgo nunca concierne más que a una sola enfermedad","Una misma enfermedad nunca está ligada más que a un único factor de riesgo"],["Multiplicidad del efecto: el tabaco causa enfermedades cardiovasculares, cánceres, EPOC, infecciones...","Eso describe la multicausalidad, no la multiplicidad del efecto.","Contrario al principio de multiplicidad del efecto.","Describe una causalidad única, en el extremo opuesto de la multiplicidad del efecto."]],
  "142": ["Entre las características siguientes, ¿cuál define un factor de riesgo?",["Una característica modificable que precede a la enfermedad y contribuye a su aparición.","Una característica endógena, no modificable, que señala a los sujetos vulnerables.","Una característica preclínica ligada a la enfermedad, sin influencia en su aparición.","Una característica necesaria y suficiente para el desarrollo de la enfermedad."],["El factor de riesgo puede controlarse o modificarse, precede al evento (criterio absoluto) y es responsable de su aparición.","Es la definición del marcador de riesgo, endógeno y no modificable.","Es la definición del indicador de riesgo, ligado a la fase preclínica y sin influencia en la aparición.","El curso precisa que un factor de riesgo no es ni necesario ni suficiente para desarrollar la enfermedad."]],
  "143": ["¿Cómo se calcula el riesgo relativo (RR)?",["Incidencia en los expuestos dividida por la incidencia en los no expuestos.","Incidencia en los no expuestos dividida por la incidencia en los expuestos.","Prevalencia en los expuestos dividida por la prevalencia en los no expuestos.","Incidencia en los expuestos dividida por la incidencia en la población total."],["El RR es efectivamente el cociente de la incidencia en los expuestos sobre la incidencia en los no expuestos.","El cociente está invertido: los expuestos van en el numerador y los no expuestos en el denominador.","El RR se construye a partir de las incidencias, no de las prevalencias.","El denominador es la incidencia en los no expuestos, y no la de la población total."]],
  "144": ["¿En qué situación se utiliza la odds ratio (OR) en lugar del riesgo relativo?",["Cuando la incidencia de la enfermedad no puede calcularse.","Cuando la prevalencia de la enfermedad no puede calcularse.","Cuando la exposición al factor de riesgo no puede medirse.","Cuando el grupo de los sujetos no expuestos no puede constituirse."],["La OR, de interpretación equivalente al RR, se utiliza cuando la incidencia no puede calcularse.","El recurso a la OR se debe a la imposibilidad de calcular la incidencia, no la prevalencia.","La OR mide la asociación con la exposición, que debe precisamente conocerse.","La OR compara expuestos y no expuestos: un grupo no expuesto sigue siendo necesario."]],
  "145": ["En relación con la estrategia de prevención dirigida a la población de alto riesgo, ¿qué afirmación es correcta?",["Se dirige a pocas personas y resulta insuficiente por sí sola.","Se dirige al conjunto de la población y basta por sí sola.","Se dirige a pocas personas y basta por sí sola para los problemas mayores.","Se dirige al conjunto de la población con nivel medio de riesgo."],["Se dirige a personas poco numerosas y se considera insuficiente por sí sola para los grandes problemas de salud pública.","Dirigirse a toda la población corresponde a la estrategia en población general.","El curso la considera al contrario insuficiente para resolver los grandes problemas de salud pública.","El nivel medio de riesgo corresponde a la estrategia en población general."]],
  "146": ["¿Para qué tipo de enfermedades es más interesante la estrategia de prevención en población general?",["Las enfermedades con incidencia elevada en la población.","Las enfermedades con incidencia baja en la población.","Las enfermedades concentradas en unos pocos sujetos de alto riesgo.","Las enfermedades de alta letalidad pero raras en la población."],["La estrategia en población general es más interesante en las enfermedades de alta incidencia.","Con una incidencia baja, el enfoque en población general pierde interés.","Los casos concentrados en los sujetos de alto riesgo corresponden a la estrategia dirigida.","El criterio establecido es la incidencia elevada, no la letalidad ni la rareza."]],
  "147": ["Según la OMS, ¿cuáles son los tres niveles de prevención?",["Prevención primaria, secundaria y terciaria.","Prevención primordial, primaria y secundaria.","Prevención primaria, secundaria y cuaternaria.","Prevención primordial, secundaria y terciaria."],["La OMS distingue tres niveles: prevención primaria, secundaria y terciaria.","La prevención primordial no la recoge la OMS; la plantean algunos autores.","La prevención cuaternaria se añade a los tres niveles de la OMS, pero no forma parte de ellos.","La primordial no se cuenta entre los tres niveles que define la OMS."]],
  "148": ["¿Qué afirmación caracteriza a la prevención primaria?",["Reduce la incidencia y se dirige a la población sana.","Reduce la prevalencia y se dirige a los enfermos asintomáticos.","Reduce las secuelas y se dirige a los enfermos sintomáticos.","Reduce la incidencia y se dirige a los enfermos sintomáticos."],["La prevención primaria actúa antes de la enfermedad, sobre la población sana, para disminuir la incidencia.","Reducir la prevalencia en los enfermos asintomáticos define la prevención secundaria.","Actuar sobre las secuelas en los enfermos sintomáticos define la prevención terciaria.","La prevención primaria se dirige a los sujetos sanos, no a los enfermos sintomáticos."]],
  "149": ["¿Cuál es el objetivo de la prevención primordial?",["Impedir la aparición de los estilos de vida de riesgo a través de los determinantes subyacentes.","Detectar precozmente la enfermedad en los sujetos todavía asintomáticos.","Reducir las secuelas de la enfermedad mediante la readaptación de los enfermos.","Evitar los daños ligados a las intervenciones médicas innecesarias."],["La prevención primordial busca evitar la instalación de los estilos de vida de riesgo abordando los determinantes subyacentes.","La detección precoz en los asintomáticos corresponde a la prevención secundaria.","Actuar sobre las secuelas y la readaptación corresponde a la prevención terciaria.","Evitar los daños de una intervención médica corresponde a la prevención cuaternaria."]],
  "150": ["El cribado de una afección en personas ya afectadas pero todavía asintomáticas, con el fin de disminuir su prevalencia, corresponde a qué nivel de prevención:",["Prevención primaria","Prevención terciaria","Prevención secundaria","Prevención cuaternaria"],["Actúa sobre sujetos sanos antes de la enfermedad para reducir la incidencia, no sobre enfermos asintomáticos.","Concierne a enfermos ya sintomáticos y busca reducir discapacidades y recidivas, no el estadio asintomático.","Se dirige a los enfermos asintomáticos y se basa en un diagnóstico y un tratamiento precoces (cribado), lo que hace bajar la prevalencia.","Busca evitar los daños ligados a la intervención médica, no el cribado de una enfermedad latente."]],
  "151": ["¿Qué proposición caracteriza correctamente la prevención terciaria?",["Se dirige a los sujetos sanos y busca impedir la aparición de la enfermedad para reducir su incidencia.","Se dirige a los enfermos sintomáticos y busca, mediante la rehabilitación y la reinserción, reducir las discapacidades y las recidivas.","Se dirige a los enfermos asintomáticos y se basa en un diagnóstico y un tratamiento precoces para disminuir la prevalencia.","Se dirige a las personas expuestas al sistema asistencial y busca limitar los daños del acto médico."],["Esa descripción corresponde a la prevención primaria, que actúa antes de la aparición de la enfermedad.","Es efectivamente la prevención terciaria: rehabilitación y reinserción del enfermo sintomático para limitar discapacidades y recidivas.","Esa descripción corresponde a la prevención secundaria (cribado), no a la prevención terciaria.","Esa descripción corresponde a la prevención cuaternaria, centrada en los daños iatrogénicos."]],
  "152": ["La prevención que busca evitar o reducir los daños causados por la propia intervención médica corresponde a qué nivel de prevención:",["Prevención primaria","Prevención secundaria","Prevención terciaria","Prevención cuaternaria"],["Impide la aparición de la enfermedad en el sujeto sano, sin relación con los daños del acto médico.","Se basa en el cribado de una enfermedad asintomática, no en la limitación de los daños médicos.","Reduce discapacidades y recidivas en el enfermo sintomático, no los efectos nocivos de la intervención.","La prevención cuaternaria tiene precisamente como finalidad evitar o limitar los daños que induce el acto médico."]],
  "153": ["¿Cómo se estima el número de casos atribuibles a una exposición en una población?",["Multiplicando el exceso de riesgo por el número de sujetos expuestos.","Multiplicando el riesgo relativo por el número de sujetos expuestos.","Dividiendo el exceso de riesgo por el número de sujetos expuestos.","Sumando el exceso de riesgo al número de sujetos expuestos."],["El número de casos atribuibles se obtiene multiplicando el exceso de riesgo (riesgo atribuible) por el efectivo expuesto.","El riesgo relativo es un cociente sin dimensión; multiplicado por el efectivo, no da un número de casos atribuibles.","Dividir el exceso de riesgo por el efectivo expuesto no proporciona un número de casos, sino una razón sin sentido aquí.","No se puede sumar un riesgo y un efectivo: la operación correcta es una multiplicación."]],
  "154": ["¿Qué consecuencia es directamente atribuible a un resultado falsamente negativo de una prueba de cribado?",["Una ansiedad importante desencadenada por el anuncio de un resultado positivo erróneo.","El recurso a exploraciones invasivas innecesarias en un sujeto finalmente sano.","Una falsa sensación de seguridad en el paciente y una pérdida de confianza en la prueba.","Una iatrogenia ligada al tratamiento de una enfermedad en realidad ausente."],["La ansiedad ante un resultado positivo erróneo caracteriza al falso positivo, no al falso negativo.","Las exploraciones invasivas injustificadas en un sujeto sano se derivan de un falso positivo.","El falso negativo tranquiliza erróneamente al enfermo y le hace perder confianza en la prueba, lo que retrasa el abordaje.","Tratar una enfermedad ausente (iatrogenia) es una consecuencia del falso positivo, no del falso negativo."]],
  "155": ["Entre estas consecuencias, ¿cuál resulta de un resultado falsamente positivo de una prueba de cribado?",["Una falsa sensación de seguridad que retrasa el abordaje del enfermo.","Una ansiedad, intervenciones invasivas y una iatrogenia en un sujeto finalmente sano.","Una pérdida de confianza en una prueba que había tranquilizado erróneamente al paciente.","Una enfermedad que evoluciona silenciosamente por no haberse detectado a tiempo."],["La falsa sensación de seguridad es una consecuencia del falso negativo, no del falso positivo.","El falso positivo inquieta erróneamente y desencadena exploraciones invasivas e iatrogenia en un sujeto realmente sano.","La pérdida de confianza tras una falsa tranquilización remite al falso negativo, no al falso positivo.","Una enfermedad no detectada que sigue evolucionando corresponde a un falso negativo."]],
  "156": ["¿Según qué criterios justifica una enfermedad la puesta en marcha de un cribado?",["Debe ser grave y frecuente, presentar una fase preclínica detectable, disponer de una prueba válida y poco costosa, pero sin una intervención precoz realmente eficaz.","Debe ser rara pero grave, sin fase preclínica detectable, con una prueba válida y poco costosa y una intervención precoz eficaz.","Debe ser grave y frecuente, carente de fase preclínica detectable, con una prueba costosa pero específica y una intervención precoz eficaz.","Debe ser grave y frecuente, presentar una fase preclínica detectable, disponer de una prueba válida y poco costosa, y contar con una intervención precoz eficaz."],["Falso: el cribado solo tiene sentido si existe una intervención precoz eficaz; sin ella, es inútil.","Falso: una enfermedad rara y desprovista de fase preclínica detectable no se presta al cribado.","Falso: una fase preclínica detectable es indispensable y la prueba debe ser poco costosa, no costosa.","Son las condiciones exigidas: gravedad, frecuencia, fase preclínica detectable, prueba válida y poco costosa, e intervención precoz eficaz."]],
  "157": ["¿Qué cualidad debe poseer con prioridad una prueba de cribado para no dejar escapar a las personas enfermas?",["Una sensibilidad elevada, con el fin de limitar los falsos negativos.","Una especificidad elevada, con el fin de limitar los falsos negativos.","Una especificidad elevada, con el fin de limitar los falsos positivos.","Una sensibilidad elevada, con el fin de limitar los falsos positivos."],["Una sensibilidad elevada detecta bien a los enfermos y minimiza los falsos negativos: es la prioridad de una prueba de cribado.","La especificidad no reduce los falsos negativos: concierne a la identificación correcta de los sujetos sanos.","Exacto en cuanto a la especificidad, pero una prueba de cribado privilegia primero la sensibilidad para no pasar por alto enfermos.","La sensibilidad limita los falsos negativos, no los falsos positivos: la asociación es incorrecta."]],
  "158": ["Una persona cuya prueba de cribado resulta positiva se deriva después a un médico para exploraciones complementarias. ¿Cuál es la característica de esas pruebas de confirmación?",["Son más específicas, generalmente más invasivas y comportan más efectos secundarios.","Son más sensibles, generalmente menos invasivas y comportan menos efectos secundarios.","Son más específicas, generalmente menos invasivas y carecen de efectos secundarios.","Son más sensibles, generalmente más invasivas, pero carecen de efectos secundarios."],["El curso precisa que las pruebas de confirmación, más específicas, son normalmente más invasivas y comportan más efectos secundarios.","Es la propia prueba de cribado la que debe ser sensible y poco invasiva, no la prueba de confirmación.","Las pruebas de confirmación son al contrario más invasivas y comportan más efectos secundarios.","Esas pruebas buscan la especificidad y no la sensibilidad, y producen más efectos secundarios."]],
  "159": ["¿Cómo se distingue un cribado simple de un cribado múltiple?",["El cribado simple se dirige a una sola enfermedad, mientras que el cribado múltiple se dirige a varias.","El cribado simple se dirige a varias enfermedades, mientras que el cribado múltiple solo se dirige a una.","El cribado simple utiliza una sola prueba repetida, mientras que el cribado múltiple encadena varias.","El cribado simple se dirige a una sola persona, mientras que el cribado múltiple a un grupo."],["El cribado simple se refiere a una sola enfermedad y el cribado múltiple a varias.","La definición está invertida: el simple solo concierne a una enfermedad y el múltiple a varias.","La distinción se basa en el número de enfermedades que se buscan, no en la repetición de las pruebas.","La distinción se basa en el número de enfermedades que se criban, no en el número de personas."]],
  "160": ["En el marco de los tipos de cribado, ¿cuál es la población a la que se dirige un cribado selectivo?",["Las personas pertenecientes a un grupo de riesgo, cuando el cribado no tiene un rendimiento universal.","El conjunto de la población general, independientemente de los factores de riesgo que presenten.","Las personas ya sintomáticas pertenecientes a uno de los grupos de riesgo conocidos.","El conjunto de la población general, cuando el cribado muestra un rendimiento universal."],["El cribado selectivo se dirige a los grupos de riesgo, en particular cuando el cribado no ha mostrado un rendimiento universal.","Dirigirse a toda la población general corresponde al cribado no selectivo.","El cribado se dirige a personas asintomáticas; el criterio es la pertenencia a un grupo de riesgo.","Dirigirse a toda la población general define el cribado no selectivo."]],
  "161": ["¿Qué conjunto corresponde a los cánceres para los que se recomienda un programa de cribado organizado?",["Cáncer de mama, cáncer de cuello de útero y cáncer de colon.","Cáncer de mama, cáncer de próstata y cáncer de colon.","Cáncer de pulmón, cáncer de cuello de útero y cáncer de colon.","Cáncer de mama, cáncer de cuello de útero y cáncer de estómago."],["El curso recomienda los programas de cribado de los cánceres de mama, de cuello de útero y de colon.","El cáncer de próstata no forma parte de ese trío recomendado.","El cáncer de pulmón no forma parte de ese trío recomendado.","El cáncer de estómago no forma parte de ese trío recomendado."]],
  "162": ["¿Cómo se define la seguridad de los pacientes?",["La reducción, a un mínimo aceptable, del riesgo de perjuicios innecesarios asociados a la asistencia sanitaria.","La eliminación total y definitiva de todo riesgo de perjuicio asociado a la asistencia sanitaria.","La reducción, a un mínimo aceptable, del coste de la asistencia sanitaria prestada al paciente.","La reducción, a un mínimo aceptable, de los perjuicios inevitables ligados a la evolución de la enfermedad."],["Es la definición establecida: llevar a un mínimo aceptable el riesgo de perjuicios innecesarios ligados a la asistencia.","Se trata de reducir el riesgo a un mínimo aceptable, no de eliminarlo totalmente.","La definición se refiere a los perjuicios, no al coste de la asistencia.","Concierne a los perjuicios innecesarios ligados a la asistencia, no a los perjuicios inevitables de la enfermedad."]],
  "163": ["¿Qué designa un evento adverso?",["Un daño ligado a la asistencia sanitaria que no corresponde a la evolución habitual del proceso.","Un daño ligado a la evolución natural de la enfermedad, independiente de la asistencia que recibe el paciente.","Un efecto adverso de un medicamento o una complicación inducida por una intervención médica.","Un evento imprevisto que provoca la muerte o un perjuicio grave, o que corre el riesgo de provocarlo."],["El evento adverso es un daño ligado a la asistencia que no corresponde a la evolución habitual del proceso.","Un evento adverso está ligado a la asistencia, y no a la sola evolución natural de la enfermedad.","Esa formulación define la enfermedad iatrogénica, no el evento adverso.","Esa formulación define el evento centinela, no el evento adverso."]],
  "164": ["¿Qué designa un evento centinela?",["Un evento imprevisto que provoca la muerte o un perjuicio grave, o que corre el riesgo de provocarlo.","Un daño ligado a la asistencia que no corresponde a la evolución habitual del proceso asistencial.","Un evento previsible que solo produce un perjuicio menor, transitorio y reversible.","Un efecto adverso de un medicamento o una complicación inducida por una intervención médica."],["El evento centinela es un evento imprevisto que provoca la muerte o un perjuicio grave, o que corre el riesgo de provocarlo.","Esa formulación corresponde al evento adverso.","El evento centinela es al contrario imprevisto y de consecuencia grave.","Esa formulación corresponde a la enfermedad iatrogénica."]],
  "165": ["En los países de rentas altas, ¿cuál es la estimación relativa a los perjuicios sufridos durante la asistencia hospitalaria?",["Alrededor de uno de cada diez pacientes hospitalizados sufre un perjuicio, de los cuales casi la mitad sería evitable.","Alrededor de uno de cada diez pacientes hospitalizados sufre un perjuicio, pero ninguno de esos perjuicios es evitable.","Alrededor de uno de cada cuatro pacientes hospitalizados sufre un perjuicio, de los cuales casi la mitad sería evitable.","Alrededor de uno de cada cien pacientes hospitalizados sufre un perjuicio, de los cuales la práctica totalidad sería evitable."],["En los países de rentas altas, alrededor de uno de cada diez pacientes sufre un perjuicio, de los cuales cerca del 50 % son evitables.","Casi la mitad de esos perjuicios se consideran al contrario evitables.","La proporción establecida es de uno de cada diez pacientes, no de uno de cada cuatro.","La proporción establecida es de uno de cada diez pacientes, no de uno de cada cien."]],
  "166": ["En atención primaria y ambulatoria, ¿cuál es la magnitud de los perjuicios que sufren los pacientes y la parte de esos perjuicios que se consideran evitables?",["Hasta 4 de cada 10 pacientes sufren un perjuicio, evitable hasta en un 80 % de los casos","Hasta 2 de cada 10 pacientes sufren un perjuicio, evitable hasta en un 60 % de los casos","Hasta 3 de cada 10 pacientes sufren un perjuicio, evitable hasta en un 70 % de los casos","Hasta 5 de cada 10 pacientes sufren un perjuicio, evitable hasta en un 90 % de los casos"],["Correcto: en ambulatorio, hasta 4 de cada 10 pacientes sufren un perjuicio, de los cuales hasta un 80 % son evitables.","Infravalora la magnitud: la proporción alcanza hasta 4 de cada 10 y no 2 de cada 10.","Cifras inexactas: es hasta 4 de cada 10 pacientes y hasta un 80 % de evitabilidad.","Sobrestima los dos valores: la frecuencia es hasta 4 de cada 10 y la evitabilidad hasta un 80 %."]],
  "167": ["¿Cómo se define la promoción de la salud?",["Un conjunto de intervenciones sociales y ambientales dirigidas a favorecer la salud y a controlar los determinantes de la salud","Un conjunto de intervenciones clínicas y farmacológicas dirigidas a tratar las enfermedades y a corregir sus complicaciones","Un conjunto de intervenciones de cribado y de diagnóstico dirigidas a detectar precozmente las enfermedades en la población","Un conjunto de intervenciones de rehabilitación y de readaptación dirigidas a restaurar las capacidades funcionales de los pacientes"],["Correcto: la promoción de la salud actúa sobre los determinantes mediante intervenciones sociales y ambientales.","Describe la asistencia curativa, no la promoción de la salud, que actúa sobre los determinantes.","Describe el cribado o la prevención secundaria, no la promoción de la salud.","Describe la readaptación, distinta de la promoción de la salud y de sus determinantes."]],
  "168": ["En relación con los actores implicados en la promoción de la salud, ¿qué afirmación es exacta?",["No corresponde únicamente al sector sanitario y moviliza otros sectores","Corresponde exclusivamente al sector sanitario y a sus profesionales","Corresponde únicamente a los centros hospitalarios y a la asistencia especializada","Corresponde solo a las autoridades sanitarias y a las agencias de salud"],["Correcto: la promoción de la salud supera el solo sector sanitario e implica a otros sectores.","Falso: no corresponde únicamente al sector sanitario.","Falso: no se limita al hospital ni a la asistencia, sino que moviliza otros sectores.","Falso: supera las solas autoridades sanitarias e implica a otros sectores."]],
  "169": ["¿Cuáles son los pilares de la promoción de la salud?",["La buena gobernanza, las ciudades saludables y los conocimientos en salud para toda la población","La buena gobernanza, la asistencia hospitalaria y la investigación biomédica para toda la población","El cribado organizado, las ciudades saludables y la cobertura vacunal para toda la población","La buena gobernanza, las ciudades saludables y el acceso a los medicamentos para toda la población"],["Correcto: son los tres pilares de la promoción de la salud.","La asistencia hospitalaria y la investigación biomédica no figuran entre los pilares de la promoción.","El cribado y la vacunación corresponden a la prevención, no a los pilares de la promoción.","El pilar esperado es el conocimiento en salud para todos, no el acceso a los medicamentos."]],
  "170": ["¿Cuál es el objetivo principal de la educación para la salud?",["Desarrollar la responsabilidad personal actuando sobre los conocimientos, las actitudes, los hábitos y el espíritu crítico","Desarrollar las competencias técnicas de los profesionales actuando sobre sus protocolos y sus gestos clínicos","Desarrollar la oferta asistencial colectiva actuando sobre las estructuras, la financiación y la organización","Desarrollar la vigilancia epidemiológica actuando sobre la recogida, el análisis y la difusión de los datos"],["Correcto: la educación para la salud busca la responsabilidad personal a través de esas cuatro dimensiones.","Se dirige a la formación de los profesionales, no a la responsabilidad personal de las personas.","Corresponde a la organización del sistema, no a la educación para la salud.","Describe la vigilancia sanitaria, distinta de la educación para la salud."]],
  "171": ["Entre los factores siguientes, ¿cuál predice con más fuerza una mala salud?",["Un nivel educativo bajo","Una edad avanzada","Un nivel económico bajo","Una situación de empleo precaria"],["Correcto: el nivel educativo bajo predice una mala salud con más fuerza que los demás factores citados.","La edad predice la mala salud con menos fuerza que el nivel educativo bajo.","El nivel económico es un determinante, pero menos predictivo que el nivel educativo.","El empleo pesa menos que el nivel educativo en la predicción de la mala salud."]],
  "172": ["¿Cómo se define la educación terapéutica?",["Actividades educativas destinadas al abordaje de las enfermedades crónicas, realizadas por profesionales formados","Actividades de cribado destinadas a la detección de las enfermedades crónicas, realizadas por profesionales formados","Actividades de rehabilitación destinadas a la recuperación funcional tras una enfermedad aguda, realizadas por profesionales formados","Actividades de investigación destinadas a la evaluación de los tratamientos de las enfermedades crónicas, realizadas por profesionales formados"],["Correcto: la educación terapéutica se dirige a la gestión de las enfermedades crónicas por profesionales formados.","El cribado no es el objeto de la educación terapéutica, que busca el abordaje.","La rehabilitación de una patología aguda no corresponde a la educación terapéutica de las enfermedades crónicas.","La investigación evaluativa no es la finalidad educativa de la educación terapéutica."]],
  "173": ["Entre las proposiciones siguientes, ¿cuál corresponde a un objetivo de la educación terapéutica?",["Reducir el recurso a urgencias y el número de hospitalizaciones","Reducir el número de profesionales implicados en el seguimiento","Reducir la duración de las consultas médicas de seguimiento","Reducir el coste de los tratamientos de la enfermedad crónica"],["Correcto: reducir urgencias y hospitalizaciones forma parte de los objetivos de la educación terapéutica.","La educación terapéutica moviliza profesionales formados y no busca reducir su número.","Acortar las consultas no forma parte de los objetivos de la educación terapéutica.","La bajada del coste de los tratamientos no es el objetivo que se enuncia para la educación terapéutica."]],
  "174": ["En el marco de la educación para la salud, ¿qué caracteriza al paciente experto (o competente)?",["Un enfermo agudo que confía por completo la gestión de su enfermedad a los profesionales sin implicarse en ella.","Un enfermo crónico convertido en actor de su propia salud y que puede servir de recurso para otros pacientes.","Un profesional sanitario formado para impartir la educación terapéutica a los enfermos crónicos.","Un enfermo crónico que sigue pasivamente las indicaciones recibidas sin intervenir nunca ante los demás."],["El paciente experto es un enfermo crónico y no agudo, y es actor de su salud en lugar de delegarla.","Definición del curso: crónico que ha aprendido a vivir con su enfermedad, actor de su salud y persona recurso para los demás.","El paciente experto es un paciente, no un profesional sanitario; la educación por los profesionales es un papel distinto.","El paciente experto es activo y puede intervenir como persona recurso; no es pasivo."]],
  "175": ["¿Cómo se define una enfermedad transmisible?",["Enfermedad debida a un agente vivo capaz de pasar de un huésped a otro y de provocar una respuesta del organismo.","Enfermedad debida a un agente químico inerte capaz de acumularse en el organismo y de provocar lesiones en él.","Enfermedad debida a un agente vivo que coloniza al huésped sin provocar nunca una respuesta ni transmitirse.","Enfermedad debida a una predisposición transmitida a la descendencia sin intervención de un agente exterior."],["Definición del curso: agente vivo apto para pasar de un huésped a otro y para inducir una respuesta del organismo.","Un agente químico inerte no es vivo y no se transmite de huésped a huésped.","Una colonización sin respuesta ni transmisión no corresponde a una enfermedad transmisible.","Una enfermedad hereditaria pasa a la descendencia, no de un huésped a otro a través de un agente vivo."]],
  "176": ["¿Qué caracteriza a una infección subclínica (o latente)?",["Una infección responsable de signos y síntomas que traducen los daños tisulares causados.","La presencia de un microorganismo que se multiplica en el huésped sin producir infección ni daño.","Una infección verdadera, contenida por la respuesta inmunitaria del huésped, sin manifestación clínica.","Una infección no controlada por la inmunidad del huésped y que se expresa con síntomas llamativos."],["La presencia de signos y síntomas define la enfermedad infecciosa, no la infección subclínica.","Es la definición de la colonización, en la que el germen se multiplica sin causar infección.","Infección subclínica o latente: sin expresión clínica, porque está limitada por la respuesta inmunitaria del huésped.","La infección subclínica está justamente contenida por la inmunidad y permanece asintomática."]],
  "177": ["¿Qué define una enfermedad infecciosa?",["La multiplicación de un germen en el huésped, en relación de comensalismo, sin provocar daño.","La expresión clínica de la infección, que asocia signos y síntomas debidos a los daños del germen y a la inflamación.","Una infección controlada por la inmunidad del huésped y que permanece totalmente desprovista de traducción clínica.","La invasión de los tejidos por un germen patógeno, pero que permanece estrictamente asintomática en el huésped."],["Una multiplicación sin daño en comensalismo corresponde a la colonización.","Enfermedad infecciosa = manifestación clínica de la infección (signos y síntomas) con daños e inflamación.","Una infección sin traducción clínica es la infección subclínica, no la enfermedad infecciosa.","Una infección asintomática no es una enfermedad infecciosa, que supone una expresión clínica."]],
  "178": ["La aparición de una enfermedad transmisible resulta de la interacción de tres elementos. ¿Cuáles?",["Un patógeno virulento, un huésped sólidamente inmunizado y un entorno desfavorable para el germen.","Un patógeno virulento, un reservorio animal y una vía de transmisión estrictamente indirecta.","Un agente químico tóxico, un huésped predispuesto y un entorno químicamente contaminado.","Un patógeno dotado de factores de virulencia, un huésped susceptible y un entorno favorable."],["Un huésped inmunizado y un medio desfavorable impiden la enfermedad; se necesitan un huésped susceptible y un medio favorable.","Reservorio y vía de transmisión son eslabones de la cadena epidemiológica, no los polos de la tríada.","La tríada se basa en un agente vivo patógeno, no en un agente químico.","La tríada asocia patógeno (virulencia), huésped susceptible y entorno favorable."]],
  "179": ["En relación con la susceptibilidad del huésped a las infecciones, ¿qué afirmación es exacta?",["Las edades extremas de la vida representan periodos de mayor sensibilidad a las infecciones.","Es la edad adulta media la que expone a la mayor sensibilidad a las infecciones.","La inmunosupresión disminuye la sensibilidad del huésped y lo protege de las infecciones.","La hiperreactividad inmunitaria pone al huésped totalmente a salvo de toda infección."],["El curso cita la edad entre los factores del huésped: las edades extremas son más sensibles.","Son las edades extremas, no la edad adulta media, las más sensibles.","La inmunosupresión aumenta al contrario la susceptibilidad del huésped a las infecciones.","La hiperreactividad inmunitaria es un factor del huésped que no confiere una protección absoluta."]],
  "180": ["¿Cómo se define el periodo de incubación?",["El tiempo que separa la exposición al agente del momento en que el sujeto se vuelve contagioso.","El tiempo durante el cual el sujeto presenta signos y síntomas de infección.","El tiempo que separa la exposición al agente patógeno de la aparición de los primeros signos y síntomas.","El lapso de tiempo durante el cual un sujeto infectado puede contagiar a su entorno."],["De la exposición a la contagiosidad es el periodo de latencia (preinfeccioso).","La presencia de los signos y síntomas corresponde al periodo clínico.","Periodo de incubación: desde la exposición al patógeno hasta la aparición de los signos y síntomas.","La duración durante la cual la infección puede transmitirse es el periodo de transmisibilidad."]],
  "181": ["¿A qué corresponde el periodo de transmisibilidad (o de contagio)?",["La duración que separa la exposición al agente patógeno de la aparición de los síntomas.","La duración durante la cual la infección puede transmitirse a un nuevo huésped.","La fase inicial, preinfecciosa, en la que el sujeto infectado todavía no tiene ningún poder contagiante.","La duración durante la cual el sujeto presenta los signos clínicos de la infección."],["De la exposición a la aparición de los síntomas es el periodo de incubación.","Periodo de transmisibilidad o contagio: duración durante la cual la infección puede transmitirse.","La fase preinfecciosa sin poder contagiante corresponde al periodo de latencia.","La presencia de los signos clínicos define el periodo clínico, no la contagiosidad."]],
  "182": ["¿Cuántos eslabones sucesivos componen la cadena epidemiológica de transmisión de un agente infeccioso?",["Siete eslabones, desde el agente hasta el huésped susceptible.","Cinco eslabones, desde el agente hasta el huésped susceptible.","Seis eslabones, desde el agente hasta el huésped susceptible.","Ocho eslabones, desde el agente hasta el huésped susceptible."],["Exacto: agente, reservorio, fuente, puerta de salida, vía de transmisión, puerta de entrada y huésped susceptible.","Falso: cinco omitiría en particular la fuente y una de las puertas; el modelo distingue siete.","Falso: seis equivaldría a fusionar dos eslabones distintos; la cadena cuenta con siete.","Falso: no se describe ningún octavo eslabón; la cadena termina en el huésped susceptible."]],
  "183": ["En la cadena epidemiológica, ¿cómo se distinguen el reservorio y la fuente?",["El reservorio es el lugar donde vive habitualmente el agente, y la fuente el lugar desde el que se transmite.","La fuente es el lugar donde vive habitualmente el agente, y el reservorio el lugar desde el que se transmite.","El reservorio y la fuente designan siempre un solo y mismo lugar de transmisión.","El reservorio es el lugar desde el que se transmite el agente, y la fuente su punto de entrada en el huésped."],["Exacto: las dos nociones son distintas y no siempre coinciden.","Falso: las definiciones están invertidas respecto del modelo.","Falso: pueden coincidir, pero no es sistemático.","Falso: el punto de entrada en el huésped es la puerta de entrada, no la fuente."]],
  "184": ["¿Qué representa la tasa de reproducción básica (R0) de un agente infeccioso?",["El número medio de casos nuevos que genera un caso en la población.","El número medio de sujetos contactos que se registran alrededor de un caso declarado.","El número medio de días que separan dos casos sucesivos de una misma cadena.","El número medio de agentes que elimina un portador en el curso de la infección."],["Exacto: es la definición del R0 como indicador de transmisibilidad.","Falso: eso corresponde al rastreo de contactos, no a la definición del R0.","Falso: es un intervalo temporal, no un número de casos generados.","Falso: el R0 cuantifica casos humanos generados, no una carga eliminada."]],
  "185": ["¿A qué corresponde la patogenicidad de un agente infeccioso?",["A su aptitud para provocar la enfermedad en el huésped.","A su aptitud para inducir una respuesta inmunitaria específica y duradera.","A su aptitud para multiplicarse en su reservorio habitual.","A su aptitud para sobrevivir en un vehículo inanimado de transmisión."],["Exacto: la patogenicidad es el poder de producir enfermedad.","Falso: eso define la inmunogenicidad, no la patogenicidad.","Falso: la supervivencia en el reservorio no define el poder patógeno.","Falso: la resistencia en un soporte corresponde a la transmisión, no a la enfermedad."]],
  "186": ["¿Qué designa la inmunogenicidad de un agente infeccioso?",["Su capacidad de inducir una respuesta inmunitaria específica y duradera.","Su capacidad de provocar la enfermedad en el huésped susceptible.","Su capacidad de transmitirse de un vertebrado al hombre.","Su capacidad de ser albergado y eliminado sin provocar síntomas."],["Exacto: es la definición de la inmunogenicidad.","Falso: ese poder de producir enfermedad corresponde a la patogenicidad.","Falso: eso caracteriza a una zoonosis, no a la inmunogenicidad.","Falso: eso describe el estado de portador, no la respuesta inmunitaria inducida."]],
  "187": ["¿Qué proposición define correctamente a un portador humano en sentido epidemiológico?",["Un sujeto que alberga y elimina el microorganismo sin presentar síntomas.","Un sujeto que alberga y elimina el microorganismo presentando síntomas.","Un sujeto que alberga el microorganismo sin eliminarlo nunca al medio.","Un sujeto que elimina el microorganismo sin haberlo albergado nunca."],["Exacto: el portador difunde el agente permaneciendo asintomático.","Falso: la presencia de síntomas es incompatible con la noción de portador.","Falso: el portador sí elimina el agente, lo que lo convierte en fuente.","Falso: la eliminación supone previamente un alojamiento del agente."]],
  "188": ["En relación con las zoonosis, ¿qué proposición es exacta?",["Son enfermedades transmitidas de los vertebrados al hombre y representan más del 60 % de las enfermedades.","Son enfermedades transmitidas del hombre a los vertebrados y representan más del 60 % de las enfermedades.","Son enfermedades transmitidas de un hombre a otro y representan más del 60 % de las enfermedades.","Son enfermedades transmitidas por un soporte inanimado y representan más del 60 % de las enfermedades."],["Exacto: la transmisión va del vertebrado al hombre y concierne a la mayoría de las enfermedades.","Falso: el sentido de la transmisión está invertido para una zoonosis.","Falso: una transmisión interhumana no es una zoonosis.","Falso: el soporte inanimado corresponde a la transmisión indirecta, no a la zoonosis."]],
  "189": ["Entre las modalidades siguientes, ¿cuál corresponde a la transmisión indirecta?",["La transmisión por un vehículo inanimado como el agua, los alimentos o los fómites.","La transmisión por contacto físico directo entre dos huéspedes sucesivos.","La transmisión por la puerta de salida del agente en su reservorio.","La transmisión por penetración a través de la puerta de entrada del huésped."],["Exacto: el vehículo inanimado, el vector y los aerosoles son vías indirectas.","Falso: el contacto directo define precisamente la transmisión directa.","Falso: la puerta de salida es un eslabón de la cadena, no un modo de transmisión.","Falso: la puerta de entrada es un eslabón de la cadena, no una vía indirecta."]],
  "190": ["¿Cómo se define un caso esporádico de una enfermedad infecciosa?",["Un caso aislado, que aparece sin vínculo aparente con otros, situación la más frecuente.","Un conjunto de casos agrupados en una misma institución en un periodo corto.","Un crecimiento rápido del número de casos en una región y un periodo dados.","Una presencia habitual y esperada de la enfermedad en una población."],["Definición exacta del caso esporádico: caso aislado, sin vínculo evidente, y modo de presentación más frecuente.","Describe un brote (epidemia limitada a una institución), no un caso aislado.","Corresponde a la definición de la epidemia, no a un caso único aislado.","Describe una situación endémica, diferente de un caso esporádico aislado."]],
  "191": ["¿Qué caracteriza a una epidemia?",["Un crecimiento rápido de la incidencia en una región y en un periodo dados.","Un caso aislado que aparece sin vínculo con otros, de la forma más frecuente.","Un aumento de los casos limitado a las personas de una sola institución.","Una presencia constante y habitual de la enfermedad en una población."],["Definición exacta de la epidemia: ascenso rápido de la incidencia, localizado en el espacio y en el tiempo.","Describe un caso esporádico, y no un aumento rápido de la incidencia.","Corresponde a un brote, forma de epidemia restringida a una institución.","Describe un estado endémico, sin el crecimiento rápido propio de la epidemia."]],
  "192": ["¿A qué corresponde un brote epidémico?",["Una epidemia limitada a las personas de una misma institución.","Un crecimiento rápido de la incidencia a escala de una región entera.","Un caso aislado, sin vínculo con otros, que constituye el modo más frecuente.","Una presencia habitual y esperada de la enfermedad en una región."],["Definición exacta del brote: epidemia circunscrita a una institución.","Describe una epidemia regional, más extensa que un brote institucional.","Corresponde a un caso esporádico, no a un grupo de casos en una institución.","Describe una endemia, sin el carácter agudo y localizado de un brote."]],
  "193": ["En la lucha contra las infecciones, ¿qué designa la desinsectación?",["La eliminación de los insectos y de los artrópodos vectores de enfermedades.","La eliminación de los roedores presentes en un entorno dado.","La administración preventiva de un antibiótico a los sujetos contactos.","La destrucción de los microorganismos presentes en una superficie dada."],["La desinsectación busca la eliminación de los insectos y artrópodos.","Se trata de la desratización, dirigida contra los roedores y no contra los insectos.","Describe la quimioprofilaxis, medida farmacológica y no antivectorial.","Corresponde a una desinfección, dirigida contra los microorganismos."]],
  "194": ["¿En qué consiste la quimioprofilaxis en la lucha contra las infecciones?",["La administración preventiva de un antibiótico a los sujetos contactos, como la rifampicina.","La administración curativa de un antibiótico a un enfermo ya sintomático.","La eliminación de los insectos y artrópodos vectores del agente infeccioso.","La inyección de una vacuna para inmunizar de forma duradera a la población expuesta."],["Definición exacta: administración preventiva de un producto químico o antibiótico a los contactos.","Se trata de un tratamiento curativo, no de una prevención en los contactos sanos.","Describe la desinsectación, medida antivectorial y no farmacológica.","Corresponde a la vacunación, que se basa en la inmunidad y no en un producto químico."]],
  "195": ["¿Qué significa la erradicación de una enfermedad infecciosa?",["Una incidencia reducida a cero con desaparición del microorganismo a escala planetaria.","Una incidencia reducida a cero, pero limitada a una región o un país dados.","Una reducción marcada de la incidencia sin desaparición del agente infeccioso.","Una desaparición del agente, incluidas las cepas conservadas en laboratorio."],["Definición exacta: incidencia nula y eliminación del agente del medio ambiente, en todo el mundo.","Describe una eliminación local, sin el alcance planetario de la erradicación.","Corresponde a un control de la enfermedad, no a una incidencia nula.","Describe la extinción, noción más estricta que la erradicación."]],
  "196": ["¿Qué enfermedad es hoy la única oficialmente erradicada?",["La viruela.","La poliomielitis.","El sarampión.","La peste."],["Única enfermedad oficialmente erradicada a escala mundial.","En vías de erradicación, pero todavía presente y, por tanto, no erradicada.","Sigue causando epidemias en el mundo, no erradicado.","Persiste en focos naturales con reservorio animal, no erradicada."]],
  "197": ["Entre las condiciones exigidas para la erradicación de una enfermedad, ¿cuál es exacta?",["El hombre debe ser el único reservorio del agente infeccioso.","La existencia de numerosos portadores sanos facilita la erradicación de la enfermedad.","Un reservorio animal importante es indispensable para lograr la erradicación.","El agente debe poder sobrevivir mucho tiempo en el medio exterior."],["La ausencia de reservorio extrahumano es una condición indispensable para la erradicación.","Falso: la ausencia de portadores sanos es al contrario necesaria.","Falso: un reservorio animal hace imposible la erradicación.","Falso: el agente debe al contrario sobrevivir poco en el medio ambiente."]],
  "198": ["En la lucha contra las infecciones, ¿qué noción designa una coexistencia con el agente patógeno en la que la incidencia y la mortalidad se reducen gracias a medidas mantenidas de forma permanente?",["El control","La eliminación","La erradicación","La extinción"],["El control reduce la incidencia y la mortalidad a un nivel aceptable coexistiendo con el agente, lo que impone medidas permanentes.","La eliminación corresponde a la ausencia de casos nuevos en una zona geográfica definida, y no a una simple reducción con coexistencia.","La erradicación es la desaparición mundial y definitiva del agente, que permite detener las medidas, al contrario que el control.","La extinción designa la desaparición total del agente, incluso en laboratorio, estadio aún más avanzado que la erradicación."]],
  "199": ["En relación con las infecciones respiratorias, ¿qué proposición es exacta?",["Más del 90 % son de origen vírico, autolimitadas y no requieren antibióticos","Alrededor del 90 % son de origen bacteriano e imponen una antibioterapia sistemática","Cerca de la mitad son víricas, y la otra mitad exige antibióticos desde el inicio","La mayoría son víricas, pero rara vez curan de forma espontánea"],["Más del 90 % de las infecciones respiratorias son víricas, de evolución espontáneamente favorable, lo que hace innecesaria la antibioterapia.","La parte bacteriana es muy minoritaria; la gran mayoría es vírica y no corresponde a los antibióticos.","La proporción vírica no es del 50 %, sino que supera el 90 %, y esas infecciones no necesitan antibióticos desde el inicio.","Al ser víricas y autolimitadas, esas infecciones curan al contrario casi siempre de forma espontánea."]],
  "200": ["¿Qué agente es responsable de la bronquiolitis del lactante?",["El virus respiratorio sincitial (VRS)","El virus gripal (Influenza)","El virus parainfluenza","El rinovirus"],["El VRS es el agente clásicamente responsable de la bronquiolitis del lactante.","El virus gripal da un síndrome gripal, pero no es el agente típico de la bronquiolitis del lactante.","El parainfluenza se asocia sobre todo a las laringitis, y no a la bronquiolitis del lactante.","El rinovirus provoca sobre todo rinitis banales y no es el agente característico de la bronquiolitis."]],
  "201": ["¿En qué consiste la transmisión aérea indirecta?",["Por aerosoles y partículas pequeñas en suspensión en el aire que alcanzan los alvéolos","Por gotículas grandes que caen rápidamente cerca de la fuente","Por contacto directo de las mucosas con un sujeto infectado","A través de las manos o de objetos contaminados"],["La vía aérea indirecta se produce por partículas pequeñas o aerosoles que permanecen en suspensión y pueden alcanzar los alvéolos.","Las gotículas grandes que sedimentan rápido corresponden a la transmisión aérea directa, a corta distancia.","El contacto directo de las mucosas no es una transmisión aérea, sino un modo de transmisión por contacto.","La transmisión por las manos o por objetos corresponde a la transmisión por contacto indirecto, no a la vía aérea."]],
  "202": ["En relación con el reservorio y la recombinación del virus gripal, ¿qué proposición es exacta?",["El reservorio natural está constituido por las aves acuáticas migratorias, y el cerdo sirve de huésped para la recombinación genética","El reservorio natural es el cerdo, y las aves migratorias aseguran la recombinación genética","El reservorio natural es el hombre, y las aves solo tienen un papel de transporte pasivo","El reservorio natural está formado por las aves domésticas, y el cerdo es un huésped puramente accidental"],["Las aves acuáticas migratorias forman el reservorio natural, y el cerdo, sensible a las cepas aviares y humanas, permite la recombinación.","El cerdo no es el reservorio, sino el lugar de recombinación; el reservorio es aviar.","El hombre no es el reservorio natural; este está representado por las aves acuáticas migratorias.","El reservorio corresponde a las aves acuáticas migratorias, y el cerdo desempeña en él un papel activo de recombinación, no accidental."]],
  "203": ["¿Cuál es el periodo de contagiosidad de la gripe?",["Desde 1 día antes de la aparición de los síntomas hasta 3 a 7 días después","Desde 3 a 7 días antes de la aparición de los síntomas hasta 1 día después","Únicamente durante la fase febril, sin contagiosidad presintomática","Desde 1 semana antes de los síntomas hasta su desaparición completa"],["El sujeto es contagioso ya el día anterior a los síntomas y lo sigue siendo de 3 a 7 días después de su inicio.","La contagiosidad solo precede a los síntomas en 1 día y se prolonga de 3 a 7 días después: la cronología inversa es falsa.","La contagiosidad comienza antes de los síntomas; no se limita, por tanto, a la sola fase febril.","La contagiosidad presintomática es solo de alrededor de 1 día, y no de una semana."]],
  "204": ["¿En qué antígenos se basa la clasificación en subtipos del virus gripal de tipo A?",["La hemaglutinina (H) y la neuraminidasa (N)","La nucleoproteína (NP) y la proteína de matriz (M)","La hemaglutinina (H) y la proteína de matriz (M)","La neuraminidasa (N) y la nucleoproteína (NP)"],["Los subtipos de gripe A se definen por las dos glucoproteínas de superficie, la hemaglutinina (H) y la neuraminidasa (N).","La nucleoproteína y la matriz sirven para definir el tipo (A, B, C), no los subtipos.","La hemaglutinina interviene efectivamente, pero es la neuraminidasa, y no la matriz, la que completa la definición del subtipo.","La neuraminidasa interviene efectivamente, pero se asocia a la hemaglutinina, y no a la nucleoproteína, para el subtipado."]],
  "205": ["En relación con las pandemias gripales, ¿qué proposición es exacta?",["Todas las pandemias son causadas por el virus gripal de tipo A","Todas las pandemias son causadas por el virus gripal de tipo B","Las pandemias resultan de una asociación de los tipos A y B","Las pandemias se deben indistintamente a los tipos A, B o C"],["Solo el tipo A, capaz de rupturas antigénicas mayores, está en el origen de las pandemias gripales.","El tipo B solo provoca epidemias estacionales, nunca una pandemia.","Las pandemias dependen únicamente del tipo A, sin asociación necesaria con el tipo B.","Los tipos B y C no causan pandemias; esta se vincula exclusivamente al tipo A."]],
  "206": ["En relación con los tipos de virus gripales, ¿qué afirmación es exacta?",["El tipo B provoca las pandemias y se reparte en varios subtipos.","El tipo B participa en las epidemias estacionales y no se clasifica en subtipos.","El tipo D participa cada invierno en las epidemias estacionales humanas.","El tipo D se clasifica en subtipos e infecta sobre todo al hombre."],["Falso: son el tipo A y sus subtipos los que provocan las pandemias, no el tipo B.","Exacto: el tipo B circula cada temporada y, al contrario que el tipo A, no se subdivide en subtipos.","Falso: el tipo D solo afecta a los animales y no causa epidemia estacional humana.","Falso: el tipo D solo infecta a los animales y no se describe en subtipos humanos."]],
  "207": ["¿Qué perfil epidemiológico caracteriza a la gripe estacional?",["Una morbilidad baja pero una mortalidad elevada.","Una morbilidad elevada y una mortalidad igualmente elevada.","Una morbilidad elevada pero una mortalidad baja.","Una morbilidad baja y una mortalidad igualmente baja."],["Falso: al contrario, afecta a numerosos sujetos y su mortalidad sigue siendo baja.","Falso: la morbilidad es efectivamente elevada, pero la mortalidad de la gripe estacional es baja.","Exacto: la gripe estacional alcanza a muchas personas (morbilidad elevada) pero mata poco (mortalidad baja).","Falso: la morbilidad es elevada, no baja; solo la mortalidad es baja."]],
  "208": ["¿Por qué complicación se producen con mayor frecuencia las muertes relacionadas con la gripe?",["Una neumonía bacteriana, con mayor frecuencia por Streptococcus pneumoniae.","Una neumonía bacteriana, con mayor frecuencia por Streptococcus pyogenes.","Una meningitis bacteriana sobreañadida por Streptococcus pneumoniae.","Una neumonía vírica primaria sin sobreinfección bacteriana."],["Exacto: las muertes se deben a menudo a una sobreinfección pulmonar bacteriana por neumococo.","Falso: la sobreinfección en causa se debe al neumococo (S. pneumoniae), no a S. pyogenes.","Falso: la complicación mortal es una neumonía, y no una meningitis, incluso por neumococo.","Falso: las muertes se vinculan sobre todo a una neumonía bacteriana sobreañadida, no a una afectación vírica aislada."]],
  "209": ["En relación con la vacunación antigripal, ¿qué proposición es exacta?",["Es anual, de composición fija, y protege desde el día de la inyección.","Se realiza una sola vez en la vida, de composición reactualizada, y protege en 2 a 3 semanas.","Es anual, de composición reactualizada, y solo protege varios meses después de la inyección.","Es anual, de composición adaptada cada año, y protege 2 a 3 semanas después de la inyección."],["Falso: la composición se reactualiza cada año y la protección es diferida de 2 a 3 semanas.","Falso: la vacuna debe repetirse cada año y no asegura una protección de por vida con una sola inyección.","Falso: la protección aparece en 2 a 3 semanas, no solamente después de varios meses.","Exacto: vacuna anual, composición adaptada cada año, protección instalada 2 a 3 semanas después de la inyección."]],
  "210": ["Tras una infección tuberculosa, ¿cuál es la evolución habitual de los bacilos?",["En el 10 % de los infectados los bacilos permanecen latentes y el 90 % evoluciona hacia la enfermedad.","En el 90 % de los infectados los bacilos permanecen latentes y el 10 % evoluciona, sobre todo los 2 primeros años.","En el 90 % de los infectados los bacilos permanecen latentes y el 10 % evoluciona, sobre todo después de diez años.","En la totalidad de los infectados los bacilos evolucionan hacia la enfermedad ya en los 2 primeros años."],["Falso: las proporciones están invertidas; es un 90 % de latencia por un 10 % de enfermedad.","Exacto: el 90 % sigue siendo infección latente, el 10 % desarrolla la enfermedad, y el riesgo es máximo los 2 primeros años.","Falso: el riesgo de evolución es máximo los 2 primeros años, y no sobre todo después de una década.","Falso: la mayoría (90 %) permanece latente; la infección no evoluciona hacia la enfermedad en todos los casos."]],
  "211": ["¿Cuál es el principal factor de riesgo de desarrollar una tuberculosis enfermedad?",["El tabaquismo crónico con broncopatía asociada.","La diabetes crónicamente descompensada y mal controlada.","La inmunodepresión ligada a la infección por el VIH/SIDA.","La desnutrición grave con carencias prolongadas."],["Falso: el tabaco puede favorecer la afectación respiratoria pero no es el principal factor de riesgo admitido.","Falso: la diabetes aumenta la susceptibilidad, pero el factor principal sigue siendo la infección por el VIH.","Exacto: el VIH/SIDA, por la inmunodepresión mayor que provoca, es el principal factor de paso a la enfermedad.","Falso: la desnutrición debilita al huésped sin constituir el principal factor de riesgo descrito."]],
  "212": ["¿Qué asociación caracteriza a la tuberculosis latente?",["No contagiosa, asintomática, radiografía normal y Mantoux positivo.","Contagiosa, sintomática, radiografía anormal y Mantoux positivo.","No contagiosa, sintomática, radiografía normal y Mantoux negativo.","Contagiosa, asintomática, radiografía anormal y Mantoux negativo."],["Exacto: la forma latente no transmite, no da síntomas, la radiografía es normal pero el Mantoux es positivo.","Falso: contagiosidad, síntomas y radiografía anormal describen la tuberculosis enfermedad, no la latente.","Falso: la forma latente es asintomática y en ella el Mantoux es positivo, no negativo.","Falso: la latente no es contagiosa ni radiológicamente anormal, y en ella el Mantoux es positivo."]],
  "213": ["¿Qué significa una prueba de Mantoux (tuberculina) positiva?",["Afirma una enfermedad activa, sin necesidad de ninguna confirmación radiológica ni bacteriológica.","Traduce una enfermedad contagiosa, confirmada de entrada por la sola prueba cutánea tuberculínica.","Traduce una inmunidad vacunal protectora, que excluye toda infección tuberculosa en curso.","Traduce una infección, no una enfermedad activa, que debe confirmarse por radiografía y cultivo."],["Falso: la prueba positiva no afirma la enfermedad activa y exige una confirmación radiológica y bacteriológica.","Falso: la prueba cutánea no confirma por sí sola una enfermedad activa ni la contagiosidad.","Falso: una prueba positiva atestigua una infección; no prueba una simple protección vacunal.","Exacto: un Mantoux positivo indica la infección; la enfermedad activa debe confirmarse por la radiografía y el cultivo."]],
  "214": ["Se diagnostica un caso de tuberculosis pulmonar contagiosa. ¿Según qué lógica se organiza el estudio de los contactos?",["En círculos concéntricos, desde los contactos más estrechos hacia los más alejados","En círculos concéntricos, desde los contactos más alejados hacia los más estrechos","Por sorteo de los contactos, con independencia de su grado de exposición","Por cribado sistemático y simultáneo de toda la población de la zona"],["Se parte del primer círculo (contactos próximos, muy expuestos) y después se amplía según los resultados: es el principio de los círculos concéntricos.","La progresión va del centro (el caso) hacia la periferia, es decir del más próximo al más alejado, y no al contrario.","La intensidad de la exposición guía la priorización de los contactos a explorar; el azar no interviene.","Se procede por círculos sucesivos dirigidos, no por un cribado masivo de entrada de toda la población."]],
  "215": ["En relación con las vías de transmisión del SARS-CoV-2, ¿qué proposición es correcta?",["Sobre todo por aerosoles y gotículas; el contacto indirecto es posible pero poco probable","Sobre todo por contacto indirecto; la transmisión por aerosoles y gotículas es poco probable","Exclusivamente por gotículas; los aerosoles no desempeñan ningún papel en la transmisión","Sobre todo por vía fecal-oral; la transmisión por gotículas es poco probable"],["La transmisión se produce principalmente por aerosoles y gotículas, y la vía por contacto indirecto se considera poco probable.","Es lo contrario: son los aerosoles y las gotículas los que dominan, y el contacto indirecto es poco probable.","Los aerosoles participan efectivamente en la transmisión; esta no se produce exclusivamente por gotículas.","La vía fecal-oral no es el modo de transmisión admitido para el SARS-CoV-2."]],
  "216": ["¿Por qué se prefiere el término «infección de transmisión sexual» (ITS) al de «enfermedad de transmisión sexual» (ETS)?",["Porque una gran parte de los casos son asintomáticos, sin enfermedad manifiesta","Porque todas esas infecciones evolucionan inevitablemente hacia una forma sintomática","Porque esas infecciones nunca se transmiten fuera de las relaciones sexuales","Porque esas infecciones solo afectan a las personas que ya están enfermas"],["La frecuencia elevada de portadores asintomáticos justifica el término «infección» antes que «enfermedad».","Al contrario, muchas siguen siendo asintomáticas; no se trata de una evolución obligada hacia la enfermedad.","El motivo del término es la existencia de casos asintomáticos, no la exclusividad de la vía sexual.","También afectan a portadores sin síntomas, lo que es precisamente la razón del término «infección»."]],
  "217": ["¿Cuál es el efecto de los casos asintomáticos de ITS sobre su difusión en la población?",["Favorecen la transmisión, porque el sujeto desconoce su infección y sigue propagándola","Limitan la transmisión, porque un sujeto sin síntomas se considera no contagioso","No tienen consecuencia sobre la transmisión, ya que solo cuentan los casos sintomáticos","Facilitan el cribado, porque la ausencia de síntomas motiva una consulta precoz"],["Un portador sin síntomas no es ni cribado ni tratado y transmite la infección, lo que favorece su difusión.","La ausencia de síntomas no significa ausencia de contagiosidad; esos casos mantienen la transmisión.","Los casos asintomáticos sí tienen un papel: contribuyen activamente a la propagación.","La ausencia de síntomas retrasa más bien la consulta y el cribado, no los facilita."]],
  "218": ["En la mujer, ¿qué complicación puede resultar de una ITS no tratada?",["Una enfermedad inflamatoria pélvica (salpingitis) que expone a la esterilidad y al embarazo extrauterino","Una endometriosis que expone a la esterilidad y a los dolores pélvicos crónicos","Un fibroma uterino que expone a las menorragias y a una compresión pélvica","Un síndrome de ovarios poliquísticos que expone a los trastornos del ciclo y a la infertilidad"],["Las ITS pueden provocar enfermedad inflamatoria pélvica, salpingitis, esterilidad, embarazo extrauterino y parto prematuro.","La endometriosis no es una complicación infecciosa de las ITS, sino una patología distinta.","El fibroma es un tumor benigno hormonodependiente, sin relación con las ITS.","El síndrome de ovarios poliquísticos es un trastorno endocrino, no una consecuencia de una ITS."]],
  "219": ["¿Qué elemento constituye un obstáculo mayor para el tratamiento de las ITS?",["La resistencia a los antibióticos, especialmente marcada en la gonorrea","La resistencia a los antibióticos, especialmente marcada en la sífilis","La resistencia a los antivirales, especialmente marcada en la gonorrea","La resistencia a los antibióticos, especialmente marcada en el VIH"],["La resistencia a los antibióticos, sobre todo la de la gonorrea, se identifica como un obstáculo mayor para el tratamiento.","Es la gonorrea la que plantea el problema de resistencia; la sífilis sigue siendo sensible a su antibiótico de referencia.","La gonorrea es una infección bacteriana tratada con antibióticos; no se trata de resistencia a los antivirales.","El VIH es un virus, no tratado con antibióticos; la resistencia afecta aquí a la gonorrea."]],
  "220": ["En relación con la evolución bajo tratamiento de las ITS bacterianas (clamidia, gonorrea, sífilis), ¿qué proposición es correcta?",["Curan gracias a un tratamiento antibiótico adaptado","No curan; los antibióticos solo ralentizan su evolución","Curan de forma espontánea, sin necesidad de un tratamiento medicamentoso","Solo curan a costa de un tratamiento antiviral prolongado"],["Las ITS bacterianas (clamidia, gonorrea, sífilis) curan con un tratamiento antibiótico.","Ese es el caso de las ITS víricas, no de las bacterianas, que sí curan con antibióticos.","La curación requiere un tratamiento antibiótico; no es espontánea.","Al ser bacterianas, dependen de los antibióticos, y no de un tratamiento antiviral."]],
  "221": ["En relación con la evolución bajo tratamiento de las ITS víricas (herpes, VPH, VIH, hepatitis), ¿qué proposición es correcta?",["No curan; los antivirales solo ralentizan su evolución","Curan de forma definitiva gracias a un tratamiento antiviral adaptado","Curan de forma definitiva gracias a un tratamiento antibiótico adaptado","Curan de forma espontánea, sin necesidad de un tratamiento particular"],["Las ITS víricas no curan; los antivirales solo ralentizan la evolución de la infección.","Los antivirales frenan la evolución pero no aportan una curación definitiva de esas infecciones víricas.","Los antibióticos actúan sobre las bacterias, no sobre esas infecciones víricas, que no curan.","Esas infecciones víricas persisten; no curan ni de forma espontánea ni bajo tratamiento."]],
  "222": ["En relación con la frecuencia de la infección por VPH en la población, ¿qué afirmación es exacta?",["Es la ITS más frecuente del mundo y al menos la mitad de las personas sexualmente activas se infectarán.","Es la ITS más frecuente del mundo pero solo afecta a una pequeña minoría de las personas sexualmente activas.","Es una ITS poco frecuente que solo alcanza a alrededor de una persona sexualmente activa de cada diez.","Es la segunda ITS más frecuente y respeta a la mayoría de las personas sexualmente activas."],["Correcto: el curso indica que el VPH es la ITS más frecuente del mundo y que al menos el 50 % de las personas sexualmente activas se infectarán.","Falso: el curso habla de al menos la mitad de las personas sexualmente activas, no de una pequeña minoría.","Falso: el VPH no es poco frecuente, sino al contrario la ITS más frecuente del mundo.","Falso: es la primera ITS en frecuencia y afecta al menos a la mitad de las personas sexualmente activas."]],
  "223": ["¿Cuál es el modo de transmisión del VPH descrito en el curso?",["Por contacto genital de piel a piel, incluso en ausencia de penetración.","Por contacto genital de piel a piel, pero únicamente cuando hay penetración completa.","Únicamente por los líquidos biológicos (sangre, semen), sin papel del contacto cutáneo.","Únicamente por vía maternofetal durante el embarazo y el parto."],["Correcto: el curso precisa que el VPH se transmite por contacto genital de piel a piel, incluso sin penetración.","Falso: la penetración no es necesaria, basta el simple contacto genital de piel a piel.","Falso: el modo de transmisión admitido es el contacto cutáneo genital, no la sola vía de los líquidos biológicos.","Falso: el curso admite la transmisión por contacto genital de piel a piel, no una vía exclusivamente maternofetal."]],
  "224": ["En relación con el vínculo entre el VPH y el cáncer de cuello uterino, ¿qué afirmación es exacta?",["Los tipos 16 y 18 son los principales tipos cancerígenos y su persistencia puede conducir al cáncer de cuello.","Los tipos 16 y 18 provocan el cáncer de cuello ya en la primoinfección, sin fase de persistencia.","Los tipos 6 y 11 son los principales tipos cancerígenos responsables del cáncer de cuello uterino.","Cualquier tipo de VPH conduce al cáncer de cuello desde el momento en que la infección persiste."],["Correcto: el curso designa los VPH 16 y 18 como principales tipos cancerígenos cuya persistencia conduce al cáncer de cuello.","Falso: es la persistencia de la infección, y no la primoinfección, la que conduce al cáncer de cuello.","Falso: el curso identifica los tipos 16 y 18 como principales tipos cancerígenos, no los tipos 6 y 11.","Falso: son específicamente los tipos 16 y 18 los designados como principales tipos cancerígenos."]],
  "225": ["¿Cuál es la recomendación de cribado del cáncer de cuello mediante citología?",["Una citología cada 3 años entre los 25 y los 65 años, esté la persona vacunada o no.","Una citología cada 3 años entre los 25 y los 65 años, únicamente en las personas no vacunadas.","Una citología cada año entre los 25 y los 65 años, esté la persona vacunada o no.","Una citología cada 5 años desde los 18 años, esté la persona vacunada o no."],["Correcto: el curso recomienda una citología cada 3 años de los 25 a los 65 años, con independencia del estado vacunal.","Falso: el cribado se recomienda esté la persona vacunada o no; la vacunación no exime de la citología.","Falso: el ritmo admitido es de 3 años, y no anual.","Falso: el cribado empieza a los 25 años y se realiza cada 3 años, no desde los 18 años cada 5 años."]],
  "226": ["¿Qué afirmación describe correctamente el VIH y su acción?",["Es un retrovirus que infecta las células del sistema inmunitario y provoca una inmunodeficiencia progresiva.","Es un retrovirus que infecta las células del sistema inmunitario pero refuerza progresivamente las defensas.","Es una bacteria que infecta las células del sistema inmunitario y provoca una inmunodeficiencia progresiva.","Es un retrovirus que infecta las células del hígado y provoca una insuficiencia hepática progresiva."],["Correcto: el curso define el VIH como un retrovirus que infecta las células inmunitarias y provoca una inmunodeficiencia progresiva.","Falso: el VIH debilita las defensas y provoca una inmunodeficiencia, no las refuerza.","Falso: el VIH es un retrovirus, no una bacteria.","Falso: el VIH tiene como diana las células del sistema inmunitario, no el hígado."]],
  "227": ["¿Qué parámetro biológico sirve para el seguimiento de la infección por VIH?",["El número de linfocitos CD4, que refleja el estado del sistema inmunitario.","El número de linfocitos CD8, que refleja el estado del sistema inmunitario.","El número de glóbulos rojos, que refleja el estado del sistema inmunitario.","El número de plaquetas, que refleja el estado del sistema inmunitario."],["Correcto: el curso indica que el número de linfocitos CD4 sirve para la vigilancia del VIH.","Falso: es el recuento de CD4, y no el de CD8, el que se utiliza para la vigilancia.","Falso: la vigilancia se basa en los linfocitos CD4, no en los glóbulos rojos.","Falso: el parámetro de vigilancia es el número de linfocitos CD4, no las plaquetas."]],
  "228": ["¿Cómo se define el estadio SIDA?",["Por una cifra de CD4 inferior a 200 células/mm³ o por la aparición de enfermedades oportunistas.","Por una cifra de CD4 superior a 200 células/mm³ o por la aparición de enfermedades oportunistas.","Por una cifra de CD4 inferior a 500 células/mm³ y por la aparición de enfermedades oportunistas.","Por una cifra de CD4 inferior a 200 células/mm³ y obligatoriamente una carga viral nula."],["Correcto: el curso define el SIDA por una cifra de CD4 inferior a 200 células/mm³ o la aparición de enfermedades oportunistas.","Falso: el umbral es una cifra de CD4 inferior a 200 células/mm³, no superior.","Falso: el umbral admitido es de 200 células/mm³, y los dos criterios son alternativos (o), no acumulativos.","Falso: el segundo criterio es la aparición de enfermedades oportunistas, no una carga viral nula."]],
  "229": ["¿Cómo se manifiesta la primoinfección por VIH?",["Por síntomas gripales que aparecen de 1 a 4 semanas después del contagio y regresan de forma espontánea.","Por síntomas gripales que aparecen de 1 a 4 semanas después del contagio y persisten de forma definitiva.","Por síntomas gripales que aparecen de 6 a 12 meses después del contagio y regresan de forma espontánea.","Por síntomas neurológicos graves que aparecen de 1 a 4 semanas después del contagio y regresan de forma espontánea."],["Correcto: el curso describe síntomas gripales que aparecen de 1 a 4 semanas después, de naturaleza autolimitada.","Falso: los síntomas de la primoinfección son autolimitados y regresan de forma espontánea.","Falso: los síntomas aparecen de 1 a 4 semanas después del contagio, no de 6 a 12 meses.","Falso: la primoinfección se traduce en síntomas gripales, no en síntomas neurológicos graves."]],
  "230": ["En relación con los modos de transmisión del VIH, ¿qué proposición es exacta?",["El VIH no se transmite ni por la saliva de un beso ni por las picaduras de mosquitos.","El VIH se transmite por el sudor y por las lágrimas de una persona infectada.","El VIH se transmite por compartir una comida o por un apretón de manos.","El VIH se transmite por la tos y por las gotículas respiratorias."],["Exacto: esas situaciones no conllevan riesgo de transmisión del VIH.","Falso: ni el sudor ni las lágrimas transmiten el VIH.","Falso: los contactos sociales ordinarios no transmiten el virus.","Falso: el VIH no tiene transmisión por vía respiratoria."]],
  "231": ["¿Qué significa el principio «Indetectable = Intransmisible» (I=I) en relación con el VIH?",["Una persona cuya carga viral es indetectable bajo tratamiento no transmite el VIH por vía sexual.","Una persona cuya carga viral es indetectable está definitivamente curada y libre del virus.","Una carga viral indetectable autoriza la interrupción definitiva del tratamiento antirretroviral.","Una persona indetectable transmite el virus pero en una forma atenuada y no patógena."],["Exacto: es la definición misma del principio I=I.","Falso: I=I no significa curación; el virus sigue presente pero controlado.","Falso: el tratamiento debe mantenerse, pues de lo contrario la carga viral vuelve a subir.","Falso: indetectable significa ausencia de transmisión, no una transmisión atenuada."]],
  "232": ["En relación con la profilaxis postexposición (PPE) al VIH, ¿qué proposición es exacta?",["Se basa en antirretrovirales iniciados en las 72 horas, durante 28 días.","Se basa en antirretrovirales iniciados en las 24 horas, durante 72 días.","Se basa en antirretrovirales iniciados en las 28 horas, durante 72 días.","Se basa en antirretrovirales iniciados en las 72 horas, durante 7 días."],["Exacto: plazo máximo de 72 horas y tratamiento de 28 días.","Falso: el plazo es de 72 horas y la duración de 28 días.","Falso: valores erróneos; el plazo es de 72 horas y la duración de 28 días.","Falso: la duración del tratamiento es de 28 días, no de 7 días."]],
  "233": ["En relación con las hepatitis víricas, ¿qué proposición es exacta?",["Existen cinco hepatitis víricas (A a E), y las hepatitis B y C son la principal causa de muerte por hepatitis.","Existen cinco hepatitis víricas (A a E), y las hepatitis A y E son la principal causa de muerte por hepatitis.","Existen tres hepatitis víricas (A, B y C), y la hepatitis A es la principal causa de muerte por hepatitis.","Existen cinco hepatitis víricas (A a E), y la hepatitis D aislada es la principal causa de muerte por hepatitis."],["Exacto: cinco virus (A a E), y la mortalidad se vincula sobre todo a B y C.","Falso: son las hepatitis B y C, no A y E, las que causan más muertes.","Falso: existen cinco hepatitis víricas, y la mortalidad se debe sobre todo a B y C.","Falso: la principal causa de muerte son B y C, no D aislada."]],
  "234": ["En los países desarrollados, ¿cuál es el principal modo de transmisión de la hepatitis B?",["La vía sexual, junto a las transmisiones parenteral, vertical y horizontal.","La vía orofecal, junto a las transmisiones parenteral, vertical y horizontal.","La vía respiratoria, junto a las transmisiones parenteral, vertical y horizontal.","La vía cutánea intacta, junto a las transmisiones parenteral, vertical y horizontal."],["Exacto: allí la transmisión es sobre todo sexual, con también las vías parenteral, vertical y horizontal.","Falso: la vía orofecal corresponde a las hepatitis A y E, no a la hepatitis B.","Falso: la hepatitis B no tiene transmisión por vía respiratoria.","Falso: la piel intacta no es una vía de transmisión del virus B."]],
  "235": ["En relación con la evolución de la hepatitis B en el adulto, ¿qué proposición es exacta?",["Evoluciona hacia la cronicidad en alrededor del 5 % de los casos, pero mucho más a menudo en el lactante.","Evoluciona hacia la cronicidad en alrededor del 50 % de los casos, pero mucho más raramente en el lactante.","Evoluciona hacia la cronicidad en alrededor del 5 % de los casos, tanto en el adulto como en el lactante.","Evoluciona hacia la cronicidad en alrededor del 95 % de los casos, pero mucho más raramente en el lactante."],["Exacto: alrededor del 5 % de cronicidad en el adulto, con un riesgo muy superior en el lactante.","Falso: la cronicidad es de alrededor del 5 % y más frecuente en el lactante.","Falso: el riesgo de cronicidad es mucho más elevado en el lactante.","Falso: la cronicidad en el adulto es de alrededor del 5 %, no del 95 %."]],
  "236": ["En relación con la prevención y el tratamiento de las hepatitis B y C, ¿qué proposición es exacta?",["La hepatitis B dispone de una vacuna universal; la hepatitis C no tiene vacuna pero sí un tratamiento que cura más del 95 % de los casos.","La hepatitis C dispone de una vacuna universal; la hepatitis B no tiene vacuna pero sí un tratamiento que cura más del 95 % de los casos.","Las hepatitis B y C disponen ambas de una vacuna universal y de un tratamiento curativo eficaz.","Ni la hepatitis B ni la hepatitis C disponen de vacuna, pero ambas tienen un tratamiento que cura más del 95 % de los casos."],["Exacto: vacunación universal para la B, sin vacuna para la C pero con un tratamiento muy eficaz.","Falso: es la hepatitis B la que tiene vacuna, no la hepatitis C.","Falso: la hepatitis C no dispone de vacuna.","Falso: la hepatitis B sí dispone de una vacuna universal."]],
  "237": ["En relación con la hepatitis A, ¿qué proposición es exacta?",["Se transmite por vía orofecal y no evoluciona hacia la cronicidad.","Se transmite por vía sexual y evoluciona con frecuencia hacia la cronicidad.","Se transmite por vía orofecal y evoluciona con frecuencia hacia la cronicidad.","Se transmite por vía parenteral y no evoluciona hacia la cronicidad."],["Exacto: transmisión orofecal y ausencia de paso a la cronicidad.","Falso: la hepatitis A es orofecal y no se vuelve crónica.","Falso: la hepatitis A no pasa a la cronicidad.","Falso: la transmisión de la hepatitis A es orofecal, no parenteral."]],
  "238": ["A propósito del origen de las infecciones transmitidas por los alimentos, ¿qué proposición es correcta?",["La mayoría son antroponosis, pues el agente se transmite de hombre a hombre a través de los alimentos","La mayoría son zoonosis, pues el agente se transmite al hombre a partir de un reservorio animal","La mayoría proceden de un reservorio puramente ambiental, sin huésped animal","La mayoría proceden de un reservorio vegetal que contamina directamente el alimento"],["La transmisión interhumana no es el mecanismo dominante: se trata sobre todo de zoonosis.","Exacto: la mayoría de las infecciones de origen alimentario son zoonosis (reservorio animal).","El reservorio dominante es animal, y no un simple reservorio ambiental.","El reservorio principal es animal, no vegetal; se trata de zoonosis."]],
  "239": ["¿Cuál es la complicación principal de las infecciones de origen alimentario, especialmente temida en las edades extremas?",["La desnutrición progresiva, sobre todo en el niño pequeño y la persona mayor","La anemia ferropénica, sobre todo en el niño pequeño y la persona mayor","La deshidratación, sobre todo en el niño pequeño y la persona mayor","La sobrecarga hídrica, sobre todo en el niño pequeño y la persona mayor"],["La complicación aguda dominante es la deshidratación, no la desnutrición.","La anemia no es la complicación principal; lo es la deshidratación.","Exacto: las pérdidas hídricas exponen a la deshidratación, grave en el niño y en el sujeto mayor.","El riesgo es la pérdida de agua (deshidratación), lo contrario de una sobrecarga."]],
  "240": ["¿Qué proposición distingue correctamente la infección alimentaria de la intoxicación alimentaria?",["Infección = microorganismos presentes en el alimento; intoxicación = toxinas presentes en el alimento","Infección = toxinas presentes en el alimento; intoxicación = microorganismos presentes en el alimento","Infección e intoxicación designan ambas la presencia de toxinas en el alimento","Infección e intoxicación designan ambas la presencia de microorganismos en el alimento"],["Correcto: la infección se basa en microorganismos en el alimento, y la intoxicación en toxinas.","Definiciones invertidas: los microorganismos definen la infección, y las toxinas la intoxicación.","La infección se basa en microorganismos presentes en el alimento, no en toxinas.","La intoxicación se basa en toxinas presentes en el alimento, no en microorganismos."]],
  "241": ["En relación con las toxinas responsables de las intoxicaciones alimentarias, ¿qué afirmación es exacta?",["La mayoría son termolábiles y se destruyen sistemáticamente con la cocción","La mayoría solo resisten a la congelación pero se destruyen con el calor","La mayoría se neutralizan con un simple recalentamiento por encima de 70 °C","La mayoría resisten al calor y no se destruyen con la cocción"],["Falso: son mayoritariamente termorresistentes, y la cocción no basta para eliminarlas.","La cocción no las destruye; esas toxinas resisten al calor.","El calentamiento, incluso por encima de 70 °C, no neutraliza esas toxinas termorresistentes.","Exacto: la mayoría de las toxinas alimentarias son termorresistentes, y la cocción no las elimina."]],
  "242": ["¿Qué agente es la causa más frecuente de los brotes epidémicos de origen alimentario?",["La listeriosis, origen de la mayoría de los brotes epidémicos alimentarios","La salmonelosis, origen de la mayoría de los brotes epidémicos alimentarios","El botulismo, origen de la mayoría de los brotes epidémicos alimentarios","La colibacilosis, origen de la mayoría de los brotes epidémicos alimentarios"],["La listeriosis es más rara pero más grave; la salmonelosis es la más frecuente.","Exacto: la salmonelosis es la causa más frecuente de los brotes epidémicos alimentarios.","El botulismo es raro (conservas artesanales); la salmonelosis domina en frecuencia.","Causa posible pero no dominante: la salmonelosis sigue siendo la más frecuente."]],
  "243": ["¿Qué zoonosis alimentaria se considera la más grave, en particular en la embarazada, el niño, la persona mayor y el inmunodeprimido?",["La listeriosis, la zoonosis alimentaria más grave en esas poblaciones de riesgo","La salmonelosis, la zoonosis alimentaria más grave en esas poblaciones de riesgo","El botulismo, la zoonosis alimentaria más grave en esas poblaciones de riesgo","La colibacilosis, la zoonosis alimentaria más grave en esas poblaciones de riesgo"],["Exacto: la listeriosis es la zoonosis alimentaria más grave, sobre todo en esas poblaciones frágiles.","La salmonelosis es la más frecuente pero no la más grave; esa es la listeriosis.","El botulismo es grave pero está ligado a las conservas; la zoonosis más grave es la listeriosis.","No es la zoonosis alimentaria descrita como la más grave; esa es la listeriosis."]],
  "244": ["En relación con el botulismo, ¿qué proposición es exacta?",["Se debe a una toxina que afecta al tubo digestivo (diarrea, vómitos), ligada a las conservas artesanales","Se debe a una bacteria invasiva que afecta al sistema nervioso, ligada al agua de bebida no potable","Se debe a una toxina que afecta al sistema nervioso (visión doble, parálisis, dificultad respiratoria), ligada a las conservas artesanales","Se debe a una toxina que afecta al hígado (ictericia, insuficiencia hepática), ligada al marisco crudo"],["La afectación del botulismo es neurológica, no digestiva; los signos son neuromusculares.","Es una toxina, no una invasión bacteriana; la fuente es la conserva, no el agua.","Exacto: toxina neurótropa (diplopía, parálisis, afectación respiratoria), con las conservas artesanales como fuente.","La afectación es neurológica, no hepática; la fuente es la conserva artesanal."]],
  "245": ["¿Qué conjunto de medidas corresponde a la prevención de las infecciones de origen alimentario?",["Agua potable, cadena del frío respetada, cocción a más de 40 °C, evitar la contaminación cruzada","Agua potable, cadena del calor mantenida, cocción a más de 70 °C, evitar la contaminación cruzada","Agua mineral con gas, cadena del frío respetada, cocción a más de 70 °C, evitar la contaminación cruzada","Agua potable, cadena del frío respetada, cocción a más de 70 °C, evitar la contaminación cruzada"],["La cocción debe superar los 70 °C; 40 °C es insuficiente para destruir los gérmenes.","Es la cadena del frío la que hay que respetar, y no una «cadena del calor».","La medida es el agua potable en general, no específicamente un agua con gas.","Exacto: agua potable, cadena del frío, cocción a más de 70 °C y prevención de la contaminación cruzada."]],
  "246": ["En transmisión vectorial, ¿cómo se define un vector?",["Un organismo vivo, con mayor frecuencia un artrópodo hematófago, que transmite un agente infeccioso.","Un soporte inanimado contaminado (agua, alimento o superficie) que vehicula pasivamente el agente infeccioso.","El microorganismo patógeno en sí mismo, directamente responsable de la enfermedad transmitida al huésped.","Un huésped animal que aloja de forma duradera el agente sin transmitirlo nunca a otro huésped."],["Un vector es un organismo vivo, típicamente un artrópodo hematófago (que se alimenta de sangre), que transmite el agente infeccioso.","Describe un vehículo o soporte inanimado; un vector es por definición un organismo vivo.","Esa es la definición del agente infeccioso, que el vector solo transmite.","Un organismo que aloja sin transmitir corresponde a un reservorio, no a un vector."]],
  "247": ["¿Qué afirmación caracteriza correctamente el paludismo?",["Una parasitosis debida a un protozoo transmitido por un mosquito, la de mayor morbimortalidad mundial.","Una infección bacteriana transmitida por un mosquito, la de mayor morbimortalidad mundial.","Una helmintiasis debida a un gusano transmitido por un mosquito, la de mayor morbimortalidad mundial.","Una virosis debida a un arbovirus transmitido por un mosquito, la de mayor morbimortalidad mundial."],["El paludismo es una parasitosis por protozoo transmitido por un mosquito; es la parasitosis de mayor morbimortalidad mundial.","El agente del paludismo es un parásito protozoo, no una bacteria.","Se trata de un protozoo, no de un gusano (helminto).","El paludismo es una parasitosis, no una virosis; el protozoo no es un virus."]],
  "248": ["¿Qué grupo es el más vulnerable al paludismo?",["Los niños menores de 5 años, que concentran alrededor del 80 % de las muertes por paludismo.","Las personas mayores de 65 años, que concentran la mayoría de las muertes por paludismo.","Los adolescentes y adultos jóvenes, en quienes la mortalidad del paludismo es la más elevada.","Los adultos en edad de trabajar, que son el grupo más afectado por la mortalidad del paludismo."],["Los niños menores de 5 años son los más vulnerables y representan alrededor del 80 % de las muertes.","Los mayores de 65 años no constituyen el grupo más vulnerable al paludismo.","No son los adolescentes ni los adultos jóvenes los que concentran la mortalidad.","El grupo más afectado es el niño menor de 5 años, no el adulto en edad de trabajar."]],
  "249": ["En el viajero, ¿en qué se basa principalmente la prevención del paludismo?",["La quimioprofilaxis medicamentosa, que debe tomarse antes, durante y después del viaje.","Una vacunación sistemática, que debe realizarse únicamente antes de la salida de viaje.","Una antibioprofilaxis oral, que debe iniciarse solo el día del regreso del viaje.","Una seroterapia curativa, que debe administrarse durante toda la estancia de riesgo."],["La prevención en el viajero se basa en la quimioprofilaxis, mantenida antes, durante y después de la estancia.","La prevención se basa en la quimioprofilaxis, no en una vacunación realizada antes de la salida.","La antibioprofilaxis no es adecuada: el paludismo es parasitario y la protección debe cubrir también el posviaje.","Una seroterapia curativa no es una medida preventiva; lo que se utiliza es la quimioprofilaxis."]],
  "250": ["¿Qué enfermedades puede transmitir el mosquito tigre (Aedes albopictus)?",["El dengue, el Zika, la fiebre amarilla y el chikunguña.","El dengue, el paludismo, la fiebre amarilla y el chikunguña.","El Zika, el chikunguña, la enfermedad de Lyme y el dengue.","La fiebre amarilla, el dengue, el tifus y el Zika."],["El mosquito tigre (Aedes albopictus) transmite dengue, Zika, fiebre amarilla y chikunguña.","El paludismo lo transmite el anofeles, no Aedes; el resto sí corresponde a Aedes.","La enfermedad de Lyme la transmite la garrapata, no el mosquito tigre.","El tifus no lo transmite Aedes albopictus."]],
  "251": ["¿Qué medida corresponde al control vectorial contra el paludismo?",["El uso de mosquiteras impregnadas y la eliminación de los reservorios de agua estancada.","El aislamiento respiratorio de los enfermos y el uso sistemático de una mascarilla de protección.","La cloración del agua de bebida y el lavado frecuente de las manos con jabón.","La cocción completa de los alimentos y la pasteurización sistemática de la leche cruda."],["El control vectorial asocia mosquiteras impregnadas, eliminación de los reservorios de agua, larvicidas y fumigación.","El aislamiento respiratorio y la mascarilla se dirigen a la transmisión aérea, no al vector.","La cloración del agua y la higiene de las manos se dirigen a la transmisión hídrica o por las manos, no al vector.","La cocción y la pasteurización se dirigen a la transmisión alimentaria, no al vector."]],
  "252": ["¿Cómo se articulan las precauciones estándar y las precauciones específicas (complementarias)?",["Las precauciones estándar se aplican a todos los pacientes; las específicas se añaden según la vía de transmisión.","Las precauciones específicas se aplican a todos los pacientes; las estándar se añaden según el germen en causa.","Las precauciones estándar sustituyen a las específicas en cuanto se identifica una vía de transmisión.","Las precauciones estándar solo se aplican a los pacientes portadores de un germen conocido y contagioso."],["Las precauciones estándar se aplican a todos los pacientes de forma permanente; las precauciones específicas se añaden según la vía de transmisión.","Es lo contrario: son las precauciones estándar, y no las específicas, las que se aplican a todos.","Las precauciones específicas se añaden a las estándar, no las sustituyen.","Las precauciones estándar se aplican a todos los pacientes, incluso sin germen identificado."]],
  "253": ["¿Qué principio fundamenta las precauciones estándar de higiene?",["Todo paciente se considera potencialmente portador de un agente transmisible.","Solo un paciente con diagnóstico infeccioso confirmado se considera realmente contagioso.","Solo un paciente que presenta síntomas visibles se considera potencialmente de riesgo.","Solo un paciente hospitalizado en habitación de aislamiento se considera portador potencial."],["Principio de las precauciones estándar: todo paciente se considera portador potencial de un agente transmisible.","No se espera un diagnóstico confirmado: todo paciente se considera portador potencial.","La ausencia de síntomas visibles no excluye el portador; todo paciente está concernido.","El principio vale para todo paciente, no solo para los que están en aislamiento."]],
  "254": ["Según los 5 momentos de la higiene de manos, ¿en qué momento debe practicarse en relación con la exposición a los líquidos biológicos?",["Antes de un riesgo de contacto con líquidos biológicos","Después de un riesgo de contacto con líquidos biológicos","Durante el contacto con líquidos biológicos","Solamente en caso de contacto comprobado con líquidos biológicos"],["El momento definido se sitúa después del riesgo de exposición, y no antes.","Es uno de los 5 momentos: higiene de manos inmediatamente después de un riesgo de exposición.","Ninguno de los 5 momentos corresponde a un gesto realizado durante el contacto.","El momento apunta al riesgo de contacto, sin esperar un contacto confirmado."]],
  "255": ["Entre las proposiciones siguientes, ¿cuál reúne los requisitos previos a la higiene de manos?",["Mangas cortas, uñas cortas sin esmalte y ausencia de toda joya","Mangas largas, uñas cortas sin esmalte y ausencia de toda joya","Mangas cortas, uñas cortas con esmalte tolerado y ausencia de joyas","Mangas cortas, uñas cortas y uso de la alianza tolerado"],["Son exactamente los requisitos exigidos, con el reloj y la alianza incluidos entre las joyas.","Las mangas deben ser cortas para dejar libres los antebrazos.","El esmalte está proscrito, incluso sobre uñas cortas.","No se admite ninguna joya, incluidas la alianza y el reloj."]],
  "256": ["En relación con la fricción hidroalcohólica, ¿qué afirmación es exacta?",["Acción bactericida muy rápida, incluso sobre manos visiblemente sucias","Acción bactericida lenta, cualquiera que sea el estado de las manos","Acción bactericida muy rápida, a condición de que las manos estén limpias y secas","Acción bactericida muy rápida, a condición de que las manos estén húmedas"],["Solo es eficaz sobre manos visualmente limpias.","Su acción es al contrario muy rápida.","La eficacia rápida supone manos visualmente limpias y secas.","Las manos deben estar secas, pues la humedad diluye el producto."]],
  "257": ["¿En qué situación es indispensable el lavado con agua y jabón?",["Cuando las manos están secas y visualmente limpias","Cuando las manos están visiblemente sucias o en caso de exposición a las esporas de C. difficile","Únicamente en caso de exposición a las esporas de Clostridium difficile","Únicamente cuando las manos están visiblemente sucias"],["En ese caso basta la fricción hidroalcohólica.","El lavado es esencial ante la suciedad visible y ante las esporas.","También lo es en cuanto las manos están visiblemente sucias.","También lo es en caso de exposición a las esporas."]],
  "258": ["¿Cuál es la conducta correcta en relación con el uso de los guantes?",["Se desinfectan los guantes por fricción entre dos gestos en un mismo paciente","Se conserva el mismo par para todos los gestos realizados en un paciente","Se cambian los guantes entre dos pacientes pero no entre dos gestos","Los guantes no se lavan, se cambian: un par por paciente y por gesto"],["Los guantes no se desinfectan, se cambian.","Hace falta un par por gesto, y no simplemente por paciente.","Se requiere un cambio en cada gesto, no solo entre pacientes.","Regla exacta: los guantes se cambian, nunca se lavan."]],
  "259": ["¿En qué momento debe realizarse la higiene de manos en relación con el uso de guantes?",["Antes y después del uso de guantes","Únicamente después de la retirada de los guantes","Únicamente antes de ponerse los guantes","Ni antes ni después, pues el uso de guantes sustituye a la higiene de manos"],["El lavado es necesario antes de ponerse los guantes y después de retirarlos.","También se requiere antes de ponerse los guantes.","También se requiere después de la retirada de los guantes.","Los guantes nunca eximen de la higiene de manos."]],
  "260": ["En caso de pinchazo accidental a través de un guante de látex, ¿cuál es el efecto sobre el volumen de sangre inoculado?",["Permanece sin cambios respecto a un pinchazo sin guante","Se reduce en alrededor del 90 %","Se reduce en alrededor del 50 %","Aumenta en alrededor del 50 %"],["El guante reduce el volumen inoculado, no lo deja sin cambios.","La reducción es del orden del 50 %, y no del 90 %.","El guante de látex disminuye en alrededor de la mitad el volumen de sangre inoculado.","El guante reduce el volumen inoculado, no lo aumenta."]],
  "261": ["En relación con las mascarillas, ¿qué correspondencia es exacta?",["Mascarilla quirúrgica: filtra el 92 %; FFP2: filtra el 98 %; FFP3: protege de las salpicaduras","Mascarilla quirúrgica: protege de las salpicaduras y de las emisiones respiratorias; FFP2: 92 %; FFP3: 98 %","Mascarilla quirúrgica: protege de las salpicaduras y de las emisiones respiratorias; FFP2: 98 %; FFP3: 92 %","FFP2: protege de las salpicaduras; mascarilla quirúrgica: 92 %; FFP3: 98 %"],["La mascarilla quirúrgica protege de las salpicaduras, no filtra el 92 %.","Correspondencia exacta de los papeles y de las tasas de filtración de las tres mascarillas.","Las tasas de filtración de la FFP2 y de la FFP3 están invertidas.","Es la mascarilla quirúrgica la que protege de las salpicaduras, no la FFP2."]],
  "262": ["En un paciente en aislamiento de tipo CONTACTO (por ejemplo colonizado por una bacteria resistente), ¿qué precauciones se añaden sistemáticamente a las medidas estándar?",["Higiene de manos, guantes y bata, y la mascarilla solo se requiere si el procedimiento lo exige.","Higiene de manos, guantes y mascarilla quirúrgica, y la bata no es sistemática.","Higiene de manos, bata y mascarilla FFP2, y los guantes no son sistemáticos.","Higiene de manos y guantes, y la bata y la mascarilla nunca se requieren."],["Exacto: en aislamiento de contacto, la higiene de manos, los guantes y la bata son sistemáticos; la mascarilla solo se requiere si la intervención lo exige.","Falso: ese perfil corresponde a las precauciones de gotículas; en contacto, es la bata la que es sistemática, no la mascarilla.","Falso: la mascarilla FFP2 corresponde a los aerosoles; en contacto, los guantes son sistemáticos y la mascarilla no se requiere.","Falso: la bata es sistemática en aislamiento de contacto, no es facultativa."]],
  "263": ["Un paciente con gripe se coloca en aislamiento de tipo GOTÍCULAS. Además de la higiene de manos, ¿qué protección respiratoria se requiere de forma permanente junto a él?",["Una mascarilla quirúrgica, llevada de forma permanente junto al paciente.","Una mascarilla FFP2, llevada de forma permanente junto al paciente.","Una mascarilla FFP3, llevada de forma permanente junto al paciente.","Ninguna mascarilla, salvo si el procedimiento realizado lo exige."],["Exacto: en aislamiento de gotículas, la mascarilla quirúrgica se lleva sistemáticamente junto al paciente.","Falso: la mascarilla FFP2 se reserva a las precauciones de aerosoles, no a las de gotículas.","Falso: la FFP3 corresponde a los aerosoles; para las gotículas, basta la mascarilla quirúrgica.","Falso: en gotículas, la mascarilla quirúrgica se requiere de forma permanente, no solo durante un procedimiento."]]
});
